package net.officefloor.hq.app.claim;

import java.math.BigDecimal;
import java.time.LocalDate;

/** A person's claim, as the store holds it. {@code id} is null until first saved. */
public class Claim {
    private Long id;
    private final String sheetId;
    private long personId;
    private BigDecimal amount;
    private LocalDate date;
    private String note;
    private ClaimStatus status;
    private String number;
    private BigDecimal settledDue;
    private String openedBy;
    private String editedBy;
    private boolean stated;
    private BigDecimal statedDue;
    private String corrects;
    private LocalDate correctedDate;
    private boolean relisted;
    private LocalDate dueBy;
    private int terms;
    private LocalDate deferredUntil;
    private int proofs;
    private String splitFrom;
    private String lockedBy;
    private boolean lateEntry;
    private LocalDate remindedOn;
    private String ref;
    private String tags;
    private String voidReason;
    private Integer settleBatch;

    public Claim(Long id, String sheetId, long personId, BigDecimal amount, LocalDate date, String note,
            ClaimStatus status, String number, BigDecimal settledDue,
            String openedBy) {
        this.id = id;
        this.sheetId = sheetId;
        this.personId = personId;
        this.amount = amount;
        this.date = date;
        this.note = note;
        this.status = status;
        this.number = number;
        this.settledDue = settledDue;
        this.openedBy = openedBy;
    }

    public Long getId() { return id; }
    public void setId(Long id) { this.id = id; }
    public String getSheetId() { return sheetId; }
    public long getPersonId() { return personId; }
    /**
     * Move it to another person: it keeps its number and date, but loses any figure a statement
     * bound it to (it is live again until its new person's next statement). A SETTLED or VOID claim
     * cannot move.
     */
    public void reassign(long toPersonId) throws InvalidClaimStatusException {
        if (status == ClaimStatus.SETTLED || status == ClaimStatus.VOID) {
            throw new InvalidClaimStatusException("A " + status + " claim cannot be moved to another person");
        }
        personId = toPersonId;
        bind(false, null);
        relisted = true;
    }
    /** Whether it was moved since read, so it is listed again as its new person's newest. */
    public boolean isRelisted() { return relisted; }
    public BigDecimal getAmount() { return amount; }
    public void setAmount(BigDecimal amount) { this.amount = amount; }
    public LocalDate getDate() { return date; }
    public void setDate(LocalDate date) { this.date = date; }
    /** Its due-by, fixed when it was made: the terms-th business day after its date (skipping weekends and the sheet's holidays then), its terms its person's own, else its grade's then. Kept when its date changes; fixed again with the same terms when a holiday on or before it is added while it is not SETTLED or VOID. */
    public LocalDate getDueBy() { return dueBy; }
    public void setDueBy(LocalDate dueBy) { this.dueBy = dueBy; }
    /** The terms (business days) its due-by was fixed with. */
    public int getTerms() { return terms; }
    public void setTerms(int terms) { this.terms = terms; }
    /** Fix its due-by: the {@code terms}-th business day after its date, skipping weekends and {@code holidays}. */
    public void fixDueBy(int terms, java.util.Set<LocalDate> holidays) {
        this.terms = terms;
        this.dueBy = net.officefloor.hq.app.holiday.HolidayRepository.businessDaysAfter(date, terms, holidays);
    }
    /** The date it is deferred until; null when it was never deferred. */
    public LocalDate getDeferredUntil() { return deferredUntil; }
    public void setDeferredUntil(LocalDate deferredUntil) { this.deferredUntil = deferredUntil; }
    /**
     * Whether it is deferred on {@code today}: OPEN, and deferred until a date after today. From
     * that date on it is an OPEN claim like any other.
     */
    public boolean isDeferredOn(LocalDate today) {
        return status == ClaimStatus.OPEN && deferredUntil != null && today != null && today.isBefore(deferredUntil);
    }
    /**
     * Defer it until a date after {@code today}: only an OPEN claim may be deferred.
     */
    public void defer(LocalDate until, LocalDate today) throws InvalidClaimStatusException, InvalidClaimException {
        if (status != ClaimStatus.OPEN) {
            throw new InvalidClaimStatusException("A " + status + " claim cannot be deferred");
        }
        if (!until.isAfter(today)) throw new InvalidClaimException("A claim is deferred to a date after today");
        deferredUntil = until;
    }
    /** How many proofs it has had added. */
    public int getProofs() { return proofs; }
    public void setProofs(int proofs) { this.proofs = proofs; }
    /** Add a proof: not to a SETTLED or VOID claim. */
    public void addProof() throws InvalidClaimStatusException {
        if (status == ClaimStatus.SETTLED || status == ClaimStatus.VOID) {
            throw new InvalidClaimStatusException("A " + status + " claim cannot have a proof added");
        }
        proofs++;
    }
    /** The last sheet's today a reminder was written for it; null when it was never reminded. */
    public LocalDate getRemindedOn() { return remindedOn; }
    public void setRemindedOn(LocalDate remindedOn) { this.remindedOn = remindedOn; }
    /** Remind it on {@code today}: only an OPEN or PENDING claim, and once per sheet's today. */
    public void remind(LocalDate today) throws InvalidClaimStatusException {
        if (!isOpen()) throw new InvalidClaimStatusException("A " + status + " claim cannot be reminded");
        if (today.equals(remindedOn)) throw new InvalidClaimStatusException("The claim was already reminded today");
        remindedOn = today;
    }
    /** Whether it was added while its period was soft-closed. */
    public boolean isLateEntry() { return lateEntry; }
    public void setLateEntry(boolean lateEntry) { this.lateEntry = lateEntry; }
    /** The number of the claim it was split off; null when it was not split off one. */
    public String getSplitFrom() { return splitFrom; }
    public void setSplitFrom(String splitFrom) { this.splitFrom = splitFrom; }
    /**
     * Split {@code part} (more than 0.00, less than its amount) off an OPEN claim that is not
     * deferred on {@code today}: it keeps the rest and loses any figure a statement bound it to.
     * The new claim is made by the caller.
     */
    public void split(BigDecimal part, LocalDate today) throws InvalidClaimStatusException, InvalidClaimException {
        if (status != ClaimStatus.OPEN) {
            throw new InvalidClaimStatusException("A " + status + " claim cannot be split");
        }
        if (isDeferredOn(today)) throw new InvalidClaimStatusException("A deferred claim cannot be split");
        if (part.signum() <= 0 || part.compareTo(amount) >= 0) {
            throw new InvalidClaimException("A split is more than 0.00 and less than the claim's amount");
        }
        amount = amount.subtract(part);
        bind(false, null);
    }
    /** The user whose editor holds it locked on the sheet's today, as read; null when no one's does. */
    public String getLockedBy() { return lockedBy; }
    public void setLockedBy(String lockedBy) { this.lockedBy = lockedBy; }
    /** Its external reference, unique on the sheet regardless of case; null when it has none. */
    public String getRef() { return ref; }
    public void setRef(String ref) { this.ref = ref; }
    /** Its tags: lower-cased, without repeats, sorted and comma separated; null when it has none. */
    public String getTags() { return tags; }
    public void setTags(String tags) { this.tags = tags; }
    /** The reason it was voided with, from the sheet's list; null when it was voided without one or is not VOID. */
    public String getVoidReason() { return voidReason; }
    public void setVoidReason(String voidReason) { this.voidReason = voidReason; }
    /** The number of the bulk settle batch that settled it; null when no bulk settle did. */
    public Integer getSettleBatch() { return settleBatch; }
    public void setSettleBatch(Integer settleBatch) { this.settleBatch = settleBatch; }
    /** Its tags, sorted; empty when it has none. */
    public java.util.List<String> tagList() {
        return tags == null ? java.util.List.of() : java.util.List.of(tags.split(","));
    }
    public String getNote() { return note; }
    public void setNote(String note) { this.note = note; }
    public ClaimStatus getStatus() { return status; }
    /** The number of the settled claim this correction corrects; null when it is no correction. */
    public String getCorrects() { return corrects; }
    public void setCorrects(String corrects) { this.corrects = corrects; }
    /** A correction (a negative amount) has no floor and no late charge. */
    public boolean isCorrection() { return corrects != null; }
    /** The date of the claim this correction corrects; null when it is no correction or not yet read. */
    public LocalDate getCorrectedDate() { return correctedDate; }
    public void setCorrectedDate(LocalDate correctedDate) { this.correctedDate = correctedDate; }
    /** The date its figures round by: a correction's is the date of the claim it corrects. */
    public LocalDate getRoundDate() {
        return isCorrection() && correctedDate != null ? correctedDate : date;
    }
    /** The claim's number on its sheet, given when it is opened; null for a draft. A voided claim
     *  keeps the number it had; a number is never reused. */
    public String getNumber() { return number; }
    public void setNumber(String number) { this.number = number; }
    /** The due fixed when it was settled; null while its due is live. */
    public BigDecimal getSettledDue() { return settledDue; }
    public void setSettledDue(BigDecimal settledDue) { this.settledDue = settledDue; }
    /** The user who opened it; null until it is opened. */
    public String getOpenedBy() { return openedBy; }
    public void setOpenedBy(String openedBy) { this.openedBy = openedBy; }
    /** The user who last edited it (its form or its row's amount entry); null when it was never edited. */
    public String getEditedBy() { return editedBy; }
    public void setEditedBy(String editedBy) { this.editedBy = editedBy; }
    /** Whether {@code user} opened it or last edited it, and so may not settle or approve it. */
    public boolean isOwnedBy(String user) {
        return user.equals(openedBy) || user.equals(editedBy);
    }
    /** Whether its person's last statement bound it to a figure. */
    public boolean isStated() { return stated; }
    /** The figure its person's last statement bound it to; null for n/a, or when it is not stated. */
    public BigDecimal getStatedDue() { return statedDue; }
    /**
     * The figure a statement binds it to now: its stated figure (null for n/a), but null when it
     * is not stated or is PENDING (a PENDING claim shows its live figure; a rejection binds it again).
     */
    public BigDecimal boundDue() {
        return isBound() ? statedDue : null;
    }
    /** Whether its stated figure is in force: it is stated and not PENDING. */
    public boolean isBound() {
        return stated && status != ClaimStatus.PENDING;
    }
    /** Bind it to a figure (null: n/a), or leave it unbound (live) when {@code stated} is false. */
    public void bind(boolean stated, BigDecimal statedDue) {
        this.stated = stated;
        this.statedDue = stated ? statedDue : null;
    }
    /**
     * Whether it counts toward its person's claimed and due-total, the sheet's totals and a
     * period's total: OPEN, PENDING and SETTLED do, except an OPEN or PENDING one dated within one
     * of its person's holds, or once their retirement date is reached ({@code heldOnDate}), unless
     * a statement binds it; and never one
     * deferred on {@code today}.
     */
    public boolean counts(boolean heldOnDate, LocalDate today) {
        if (isDeferredOn(today)) return false;
        return status == ClaimStatus.SETTLED || (isOpen() && (isBound() || !heldOnDate));
    }
    /**
     * Whether it counts toward a period's total as it was at the period's end, when its status then
     * was {@code statusThen} (null: it did not exist yet): as {@link #counts} with that status, its
     * statement binding and deferral as they are now.
     */
    public boolean countsAsOf(ClaimStatus statusThen, boolean heldOnDate, LocalDate today) {
        if (statusThen == null || isDeferredOn(today)) return false;
        boolean openThen = statusThen == ClaimStatus.OPEN || statusThen == ClaimStatus.PENDING;
        return statusThen == ClaimStatus.SETTLED || (openThen && (isBound() || !heldOnDate));
    }
    /**
     * A copy of it as it stood at the end of a day: with the status, settled due and statement
     * binding it had then, the rest as it is now.
     */
    public Claim asThen(ClaimStatus statusThen, BigDecimal settledDueThen, boolean statedThen, BigDecimal statedDueThen) {
        Claim then = new Claim(id, sheetId, personId, amount, date, note, statusThen, number, settledDueThen, openedBy);
        then.bind(statedThen, statedDueThen);
        then.corrects = corrects;
        then.correctedDate = correctedDate;
        then.dueBy = dueBy;
        then.terms = terms;
        then.deferredUntil = deferredUntil;
        then.proofs = proofs;
        then.splitFrom = splitFrom;
        then.lateEntry = lateEntry;
        then.remindedOn = remindedOn;
        then.ref = ref;
        then.tags = tags;
        then.voidReason = voidReason;
        then.settleBatch = settleBatch;
        then.editedBy = editedBy;
        return then;
    }
    /** Whether it is open: OPEN, or PENDING a steward's approval. */
    public boolean isOpen() {
        return status == ClaimStatus.OPEN || status == ClaimStatus.PENDING;
    }
    /** Only a draft may be edited; to change an open claim, void it and add a new one. */
    public void checkEditable() throws InvalidClaimStatusException {
        if (status != ClaimStatus.DRAFT) throw new InvalidClaimStatusException(status);
    }

    /** A steward's approval of a PENDING claim: it is settled, its due fixed at {@code due}. */
    public void approve(BigDecimal due) throws InvalidClaimStatusException {
        if (status != ClaimStatus.PENDING) throw new InvalidClaimStatusException(status, ClaimStatus.SETTLED);
        status = ClaimStatus.SETTLED;
        settledDue = due;
    }
    /** A steward's rejection of a PENDING claim: it is OPEN again, bound again by its statement. */
    public void reject() throws InvalidClaimStatusException {
        if (status != ClaimStatus.PENDING) throw new InvalidClaimStatusException(status, ClaimStatus.OPEN);
        status = ClaimStatus.OPEN;
        settleBatch = null;
    }

    /** Move to the next status, when the current one allows it. */
    public void moveTo(ClaimStatus next) throws InvalidClaimStatusException {
        if (!status.canMoveTo(next)) throw new InvalidClaimStatusException(status, next);
        status = next;
    }
}
package net.officefloor.hq.app.claim;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.time.LocalDate;
import java.time.temporal.ChronoUnit;
import java.util.List;
import net.officefloor.hq.app.rate.Rate;
import net.officefloor.hq.app.setting.Settings;

/**
 * A claim's figures, as the screen shows them. Its rate figure: the figure its person's last
 * statement bound it to (never while it is PENDING), else its amount times its grade's rate in
 * force on its date, divided by 100 and rounded to two decimals. Its live due: the greater of the
 * sheet's floor in force on its date and its rate figure plus its late charge (worked out on the
 * rate figure alone); a correction, a negative amount, has no floor and no late charge. A settled
 * claim's due stays as it was fixed. Null for n/a (no floor applies to n/a). Every rounding of a
 * claim's live figures is by the sheet's policy date ({@link Settings#rounding}): half up when the
 * claim is dated before it, half to even on or after; a correction rounds by the date of the claim
 * it corrects.
 */
public final class ClaimFigure {
    private ClaimFigure() {}

    /** The claim's rate figure: its bound figure when a statement bound it, else its live rate figure. */
    public static BigDecimal of(Claim claim, List<Rate> rates, String grade, Settings settings, LocalDate today) {
        if (claim.isBound()) return claim.getStatedDue();
        return live(claim, rates, grade, settings, today);
    }

    /** The claim's amount at its grade's rate on its date, before any floor or late charge. */
    public static BigDecimal live(Claim claim, List<Rate> rates, String grade, Settings settings, LocalDate today) {
        RoundingMode mode = rounding(claim, settings, today);
        return Rate.inForce(rates, grade, claim.getDate())
                .map((pct) -> times(claim.getAmount(), pct, mode))
                .orElse(null);
    }

    /**
     * The due on a rate figure with a late charge: the greater of the floor in force on the claim's
     * date and the figure plus the charge; a correction has no floor. Null for n/a.
     */
    public static BigDecimal floored(Claim claim, BigDecimal figure, BigDecimal late, Settings settings) {
        if (figure == null) return null;
        BigDecimal due = figure.add(late);
        return claim.isCorrection() ? due : due.max(settings.floorOn(claim.getDate()));
    }

    /** How the claim's live figures round, by the date it rounds by and the sheet's policy date. */
    public static RoundingMode rounding(Claim claim, Settings settings, LocalDate today) {
        return settings.rounding(claim.getRoundDate(), today);
    }

    /**
     * The claim's due as the screen shows it: the due fixed when it was settled, else its live due
     * ({@link #floored}) on its rate figure ({@link #of}) and the late charge an OPEN or PENDING claim
     * gains on that figure while overdue on {@code today}. Null for n/a.
     */
    public static BigDecimal withLate(Claim claim, List<Rate> rates, String grade, Settings settings,
            LocalDate today) {
        if (claim.getSettledDue() != null) return claim.getSettledDue();
        BigDecimal figure = of(claim, rates, grade, settings, today);
        return figure == null ? null : floored(claim, figure, late(claim, figure, grade, settings, today), settings);
    }

    /**
     * The late charge on a figure: for an OPEN or PENDING claim past its due-by (fixed when it was made)
     * plus the grace days of its grade ({@code grade}, the one in force on its date) on its date
     * ({@link Settings#overdueFrom}) on {@code today}, for every full 30 days it is overdue the
     * sheet's late percent in force on that boundary date (that day plus 30, 60, 90 ... days) of the figure plus the
     * charges of the boundaries before it (compounding), each rounded to two
     * decimals as the claim rounds, added up; else 0.00 (as for a claim deferred on today). Never bound by a statement:
     * it follows the sheet's today until the claim is settled.
     */
    public static BigDecimal late(Claim claim, BigDecimal figure, String grade, Settings settings, LocalDate today) {
        if (!claim.isOpen() || claim.isDeferredOn(today)) return BigDecimal.ZERO.setScale(2);
        return lateAsOpen(claim, figure, grade, settings, today);
    }

    /** The late charge on a figure as {@link #late} reads it for an open claim, whatever the claim's status. */
    public static BigDecimal lateAsOpen(Claim claim, BigDecimal figure, String grade, Settings settings,
            LocalDate today) {
        BigDecimal none = BigDecimal.ZERO.setScale(2);
        if (figure == null || claim.isCorrection()) return none;
        LocalDate from = settings.overdueFrom(claim.getDueBy(), grade, claim.getDate());
        long overdue = ChronoUnit.DAYS.between(from, today);
        long periods = overdue > 0 ? overdue / 30 : 0;
        RoundingMode mode = rounding(claim, settings, today);
        BigDecimal charge = none;
        for (long k = 1; k <= periods; k++) {
            BigDecimal pct = settings.latePctOn(from.plusDays(30 * k));
            if (pct.signum() != 0) charge = charge.add(times(figure.add(charge), pct, mode));
        }
        return charge;
    }

    /** The amount times the percent, divided by 100 and rounded to two decimals. */
    private static BigDecimal times(BigDecimal amount, BigDecimal pct, RoundingMode mode) {
        return amount.multiply(pct).divide(BigDecimal.valueOf(100), 2, mode);
    }
}
package net.officefloor.hq.app.rollup;

import jakarta.servlet.http.HttpServletRequest;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.claim.ClaimRepository;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.rate.RateRepository;
import net.officefloor.hq.app.setting.SettingsRepository;
import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.hq.app.sheet.SheetRepository;
import net.officefloor.plugin.variable.Val;

/**
 * Records, after the change's own lines, the figures it moved: a ROLLUP line per person whose
 * claimed, due-total or overdue-total changed, then a TOTALS line when the sheet's totals changed. The sheet's
 * today is read again, as the change may have moved it.
 */
public class AuditRollup {
    public void audit(@Val Sheet sheet, @Val Rollup before, SheetRepository sheets, PersonRepository people,
            ClaimRepository claims, RateRepository rates, SettingsRepository settings, HttpServletRequest request, Audit audit) {
        Rollup after = Rollup.of(sheet.id(), sheets.today(sheet.id()), people, claims, rates,
                settings.find(sheet.id()));
        after.changesSince(before, sheet.id(), Audit.user(request)).forEach(audit::record);
    }
}
package net.officefloor.hq.app.rollup;

import jakarta.servlet.http.HttpServletRequest;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.plugin.variable.Val;

/**
 * Records, before the sheet's today changes, a SNAPSHOT line per person in list order with their
 * due-total as it stood on the day being left.
 */
public class AuditSnapshot {
    public void audit(@Val Sheet sheet, @Val Rollup before, HttpServletRequest request, Audit audit) {
        String head = " sheet=" + sheet.id() + " by=" + Audit.user(request);
        before.people().values().forEach((figures) -> audit.record(
                "SNAPSHOT" + head + " name=" + figures.name() + " due-total=" + figures.dueTotal()));
    }
}
package net.officefloor.hq.app.rollup;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.ClaimFigure;
import net.officefloor.hq.app.claim.ClaimRepository;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.rate.Rate;
import net.officefloor.hq.app.rate.RateRepository;
import net.officefloor.hq.app.setting.Settings;

/**
 * The sheet's figures as the screen shows them: each person's claimed, due-total and overdue-total (by person id,
 * in the order they were added), and the sheet's claimed-total, due-total and overdue-total.
 */
public record Rollup(Map<Long, Figures> people, String claimedTotal, String dueTotal, String overdueTotal) {

    /** A person's figures: their name, claimed, due-total (n/a when none) and overdue-total. */
    public record Figures(String name, String claimed, String dueTotal, String overdueTotal) {
        boolean sameFigures(Figures other) {
            return other != null && claimed.equals(other.claimed) && dueTotal.equals(other.dueTotal)
                    && overdueTotal.equals(other.overdueTotal);
        }
    }

    /**
     * The sheet's figures now. A person's claimed is the amounts of their claims that count (OPEN
     * and SETTLED, but not an unbound OPEN one dated within one of their holds) added up; their due-total the figures of those claims added up, skipping n/a (a live due is the greater of the floor on its date and its rate figure plus the late
     * charge it gains on {@code today}), and
     * n/a when their grade in force today has no rate today and no claim that counts keeps a fixed
     * figure or has one under the grade in force on its date when that is another grade, or
     * has one dated on or before today (under a rate that has since ended), held to the sheet's cap. Each claim
     * takes the rate of the grade in force on its date. The
     * sheet's totals add these up, skipping n/a; with three or more figures, the due-total and
     * overdue-total leave out the single highest and the single lowest.
     */
    public static Rollup of(String sheetId, LocalDate today, PersonRepository people, ClaimRepository claims,
            RateRepository rates, Settings settings) {
        List<Rate> all = rates.findAll(sheetId);
        List<Claim> sheetClaims = claims.findAll(sheetId);
        Map<Long, Figures> figures = new LinkedHashMap<>();
        BigDecimal claimedTotal = BigDecimal.ZERO.setScale(2);
        List<BigDecimal> dues = new ArrayList<>();
        List<BigDecimal> overdues = new ArrayList<>();
        for (Person person : people.findAll(sheetId)) {
            BigDecimal claimed = BigDecimal.ZERO.setScale(2);
            BigDecimal due = BigDecimal.ZERO.setScale(2);
            BigDecimal overdue = BigDecimal.ZERO.setScale(2);
            boolean fixed = false;
            for (Claim claim : sheetClaims) {
                if (claim.getPersonId() != person.getId()) continue;
                if (!claim.counts(person.heldOn(claim.getDate(), today), today)) continue;
                claimed = claimed.add(claim.getAmount());
                if (claim.getSettledDue() != null || claim.boundDue() != null) fixed = true;
                String grade = person.gradeOn(claim.getDate());
                BigDecimal figure = ClaimFigure.withLate(claim, all, grade, settings, today);
                if (figure != null) due = due.add(figure);
                if (figure != null && overdue(claim, grade, settings, today)) overdue = overdue.add(figure);
                // A figure found under a grade other than today's is kept, whatever today's rate.
                if (figure != null && !grade.equals(person.gradeOn(today))) fixed = true;
                // So is one dated on or before today, found under a rate that has since ended.
                if (figure != null && !claim.getDate().isAfter(today)) fixed = true;
            }
            boolean none = Rate.inForce(all, person.gradeOn(today), today).isEmpty() && !fixed;
            claimedTotal = claimedTotal.add(claimed);
            overdues.add(overdue);
            due = settings.capped(due, today);
            if (!none) dues.add(due);
            figures.put(person.getId(), new Figures(person.getName(), show(claimed), none ? "n/a" : show(due),
                    show(overdue)));
        }
        return new Rollup(figures, show(claimedTotal), show(trimmed(dues)), show(trimmed(overdues)));
    }

    /** People's figures added up: with three or more, the single highest and single lowest left out. */
    private static BigDecimal trimmed(List<BigDecimal> values) {
        List<BigDecimal> sorted = new ArrayList<>(values);
        sorted.sort(BigDecimal::compareTo);
        if (sorted.size() >= 3) sorted = sorted.subList(1, sorted.size() - 1);
        return sorted.stream().reduce(BigDecimal.ZERO.setScale(2), BigDecimal::add);
    }

    /**
     * Whether a claim is overdue on {@code today}: open (OPEN or PENDING) and past its due-by plus the
     * grace days of its grade on its date ({@link Settings#overdueFrom}).
     */
    private static boolean overdue(Claim claim, String grade, Settings settings, LocalDate today) {
        return claim.isOpen() && today != null && claim.getDueBy() != null
                && settings.overdueFrom(claim.getDueBy(), grade, claim.getDate()).isBefore(today);
    }

    /**
