        String value = valueOn(gradeTermsKey(grade), date);
        return value == null || value.isEmpty() ? null : Integer.valueOf(value);
    }

    /** The terms of a person's claim on a date: their own, else their grade's then, else the sheet's. */
    public int termsFor(net.officefloor.hq.app.person.Person person, LocalDate date) {
        Integer own = person.getTerms();
        return own != null ? own : termsFor(person.gradeOn(date), date);
    }

    /** The terms of a grade on a date: its own, else the sheet's. */
    public int termsFor(String grade, LocalDate date) {
        Integer own = gradeTermsOn(grade, date);
        return own != null ? own : termsOn(date);
    }

    /** The clerk limit in force on a date (null: no limit). */
    public BigDecimal clerkLimitOn(LocalDate date) {
        return figureOn(CLERK_LIMIT, date);
    }

    /** The proof threshold in force on a date (null: none). */
    public BigDecimal proofThresholdOn(LocalDate date) {
        return figureOn(PROOF_THRESHOLD, date);
    }

    /**
     * The proof threshold of a claim of a grade dated {@code date}: the grade's own in force on that
     * date when it has one, else the sheet's (null: none).
     */
    public BigDecimal proofThresholdFor(String grade, LocalDate date) {
        BigDecimal own = grade == null ? null : gradeProofThresholdOn(grade, date);
        return own != null ? own : proofThresholdOn(date);
    }

    /**
     * Whether a claim of a grade dated {@code date} with a due (null: n/a) and a proofs count needs
     * a proof before it is settled or approved: its due is above its proof threshold and it has no
     * proofs. A due of n/a, or no threshold, needs none.
     */
    public boolean needsProof(BigDecimal due, String grade, LocalDate date, int proofs) {
        BigDecimal threshold = proofThresholdFor(grade, date);
        return proofs == 0 && threshold != null && due != null && due.compareTo(threshold) > 0;
    }

    /** The note threshold in force on a date (null: none). */
    public BigDecimal noteThresholdOn(LocalDate date) {
        return figureOn(NOTE_THRESHOLD, date);
    }

    /**
     * Whether a claim dated {@code date} with a due (null: n/a) and a note needs a note before it is
     * opened: its due is above the note threshold in force on its date and its note is empty. A due
     * of n/a, or no threshold, needs none.
     */
    public boolean needsNote(BigDecimal due, LocalDate date, String note) {
        BigDecimal threshold = noteThresholdOn(date);
        return (note == null || note.isBlank()) && threshold != null && due != null && due.compareTo(threshold) > 0;
    }

    /** The cap in force on a date (null: none). */
    public BigDecimal capOn(LocalDate date) {
        return figureOn(CAP, date);
    }

    /**
     * How every figure of a claim that rounds by {@code date} is rounded: half up before the policy
     * date ({@code today} when it is blank), half to even on or after it.
     */
    public RoundingMode rounding(LocalDate date, LocalDate today) {
        LocalDate policy = policyDate != null ? policyDate : today;
        return date.isBefore(policy) ? RoundingMode.HALF_UP : RoundingMode.HALF_EVEN;
    }

    /** The date of a new claim left undated: the entry date while it is set, else the sheet's today. */
    public LocalDate entryDay(LocalDate today) {
        return entryDate != null ? entryDate : today;
    }

    /** Whether a period ending {@code to} is past its grace days on {@code today}: never while they are off. */
    public boolean pastGrace(LocalDate to, LocalDate today) {
        return graceDays != null && to.plusDays(graceDays).isBefore(today);
    }

    /** Whether a claim opened on {@code today} is numbered within its period. */
    public boolean numbersByPeriod(LocalDate today) {
        return periodNumberingFrom != null && !today.isBefore(periodNumberingFrom);
    }

    /** A person's due-total (null: n/a) held to the cap in force on {@code today}. A due-total of n/a is not capped. */
    public BigDecimal capped(BigDecimal dueTotal, LocalDate today) {
        BigDecimal cap = capOn(today);
        return cap == null || dueTotal == null || dueTotal.compareTo(cap) <= 0 ? dueTotal : cap;
    }

    /** Whether a due (null: n/a) is within the clerk limit in force on {@code today}. A due of n/a is within any limit. */
    public boolean withinClerkLimit(BigDecimal due, LocalDate today) {
        BigDecimal clerkLimit = clerkLimitOn(today);
        return clerkLimit == null || due == null || due.compareTo(clerkLimit) <= 0;
    }
}
package net.officefloor.hq.app;

import jakarta.servlet.http.HttpServletRequest;
import java.time.LocalDate;
import java.time.format.DateTimeParseException;

/**
 * The as-of date the signed-in user's screen reads the sheet at, named on each read in the
 * {@code X-As-Of} header (yyyy-MM-dd). While it is set, a read answers with the sheet as it stood at
 * the end of that date: every change made while the sheet's today was on or before it, and that
 * date standing in for the sheet's today. Changes never carry it.
 */
public final class AsOf {

    public static final String HEADER = "X-As-Of";

    private AsOf() {
    }

    /** The as-of date the request reads at, or null when it reads the sheet as it is now. */
    public static LocalDate of(HttpServletRequest request) {
        String raw = request == null ? null : request.getHeader(HEADER);
        if (raw == null || raw.isBlank()) return null;
        try {
            return LocalDate.parse(raw.trim());
        } catch (DateTimeParseException e) {
            return null;
        }
    }
}
package net.officefloor.hq.app.person;

import java.time.LocalDate;
import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import java.util.TreeMap;

/** A person on a sheet, as the store holds it. {@code id} is null until first saved. */
public class Person {
    private Long id;
    private final String sheetId;
    private String name;
    private String grade;
    private Integer terms;
    private String contact;
    private long version;
    private int statementCount;
    private String statedTotal;
    private LocalDate statementDate;
    private LocalDate retiredFrom;
    private LocalDate addedOn;
    private final List<Hold> holds = new ArrayList<>();
    private final List<Long> patronIds = new ArrayList<>();
    private final TreeMap<LocalDate, String> datedGrades = new TreeMap<>();

    public Person(Long id, String sheetId, String name, String grade) {
        this(id, sheetId, name, grade, 0);
    }

    public Person(Long id, String sheetId, String name, String grade, long version) {
        this.id = id;
        this.sheetId = sheetId;
        this.name = name;
        this.grade = grade;
        this.version = version;
    }

    public Long getId() { return id; }
    public void setId(Long id) { this.id = id; }
    public String getSheetId() { return sheetId; }
    public String getName() { return name; }
    public void setName(String name) { this.name = name; }
    /** The first grade they were given: in force from the beginning of time, until their first dated grade. */
    public String getGrade() { return grade; }
    public void setGrade(String grade) { this.grade = grade; }
    /** Their own terms in days, ahead of their grade's and the sheet's; null when they have none. */
    public Integer getTerms() { return terms; }
    public void setTerms(Integer terms) { this.terms = terms; }
    /** Their contact, trimmed and lower-cased; null when they have none. */
    public String getContact() { return contact; }
    public void setContact(String contact) { this.contact = contact; }
    /** The grades recorded from a date, by from-date: each in force from it until the next. */
    public Map<LocalDate, String> getDatedGrades() { return datedGrades; }
    /** Record the grade from this date, replacing any recorded from the same date. */
    public void setGradeFrom(String grade, LocalDate from) { datedGrades.put(from, grade); }
    /** The grade in force on the date: the latest dated one on or before it, else the first grade. */
    public String gradeOn(LocalDate date) {
        Map.Entry<LocalDate, String> dated = datedGrades.floorEntry(date);
        return dated == null ? grade : dated.getValue();
    }
    /** Raised by one on each save; an edit names the version it was made from. */
    public long getVersion() { return version; }
    public void setVersion(long version) { this.version = version; }
    /** How many statements have been taken for them. */
    public int getStatementCount() { return statementCount; }
    /** The last statement's due-total (n/a when it had none); null before the first. */
    public String getStatedTotal() { return statedTotal; }
    /** The sheet's today when the last statement was taken; null before the first. */
    public LocalDate getStatementDate() { return statementDate; }
    public void setStatements(int count, String statedTotal, LocalDate statementDate) {
        this.statementCount = count;
        this.statedTotal = statedTotal;
        this.statementDate = statementDate;
    }
    /** The sheet's today when they were added; null when it was not kept (from the beginning of time). */
    public LocalDate getAddedOn() { return addedOn; }
    public void setAddedOn(LocalDate addedOn) { this.addedOn = addedOn; }
    /** Whether they had been added by the end of {@code day}. */
    public boolean addedBy(LocalDate day) { return addedOn == null || !addedOn.isAfter(day); }
    /** The date they are retired from; null when not retired. Set at all, they count as retired. */
    public LocalDate getRetiredFrom() { return retiredFrom; }
    public void setRetiredFrom(LocalDate retiredFrom) { this.retiredFrom = retiredFrom; }
    public boolean isRetired() { return retiredFrom != null; }
    /** Their holds, in the order added: each from a date to an optional to-date. */
    public List<Hold> getHolds() { return holds; }
    /** Whether they have any hold at all. */
    public boolean isHeld() { return !holds.isEmpty(); }
    /** Whether the date is within one of their holds: an OPEN claim on it, not bound by a statement, counts in no total. */
    public boolean heldOn(LocalDate date) { return holds.stream().anyMatch((h) -> h.covers(date)); }
    /** Whether their retirement date is reached on {@code today}: retired from it or an earlier date. */
    public boolean retiredOn(LocalDate today) { return retiredFrom != null && today != null && !today.isBefore(retiredFrom); }
    /**
     * Whether an OPEN or PENDING claim of theirs on the date, not bound by a statement, counts in no
     * total on {@code today}: the date is within one of their holds, or their retirement date is reached.
     */
    public boolean heldOn(LocalDate date, LocalDate today) { return heldOn(date) || retiredOn(today); }
    /** The ids of the people they name as patrons, in the order named. */
    public List<Long> getPatronIds() { return patronIds; }
    /** Whether a claim on this date is refused: they are retired from an earlier date. */
    public boolean retiredBefore(LocalDate date) { return retiredFrom != null && date.isAfter(retiredFrom); }
}

