283	
284	    /** Move to the next status, when the current one allows it. */
285	    public void moveTo(ClaimStatus next) throws InvalidClaimStatusException {
286	        if (!status.canMoveTo(next)) throw new InvalidClaimStatusException(status, next);
287	        status = next;
288	    }
289	}
290	package net.officefloor.hq.app.claim;
291	
292	import java.math.BigDecimal;
293	import java.math.RoundingMode;
294	import java.time.LocalDate;
295	import java.time.temporal.ChronoUnit;
296	import java.util.List;
297	import net.officefloor.hq.app.rate.Rate;
298	import net.officefloor.hq.app.setting.Settings;
299	
300	/**
301	 * A claim's figures, as the screen shows them. Its rate figure: the figure its person's last
302	 * statement bound it to (never while it is PENDING), else its amount times its grade's rate in
303	 * force on its date, divided by 100 and rounded to two decimals. Its live due: the greater of the
304	 * sheet's floor in force on its date and its rate figure plus its late charge (worked out on the
305	 * rate figure alone); a correction, a negative amount, has no floor and no late charge. A settled
306	 * claim's due stays as it was fixed. Null for n/a (no floor applies to n/a). Every rounding of a
307	 * claim's live figures is by the sheet's policy date ({@link Settings#rounding}): half up when the
308	 * claim is dated before it, half to even on or after; a correction rounds by the date of the claim
309	 * it corrects.
310	 */
311	public final class ClaimFigure {
312	    private ClaimFigure() {}
313	
314	    /** The claim's rate figure: its bound figure when a statement bound it, else its live rate figure. */
315	    public static BigDecimal of(Claim claim, List<Rate> rates, String grade, Settings settings, LocalDate today) {
316	        if (claim.isBound()) return claim.getStatedDue();
317	        return live(claim, rates, grade, settings, today);
318	    }
319	
320	    /** The claim's amount at its grade's rate on its date, before any floor or late charge. */
321	    public static BigDecimal live(Claim claim, List<Rate> rates, String grade, Settings settings, LocalDate today) {
322	        RoundingMode mode = rounding(claim, settings, today);
323	        return Rate.inForce(rates, grade, claim.getDate())
324	                .map((pct) -> times(claim.getAmount(), pct, mode))
325	                .orElse(null);
326	    }
327	
328	    /**
329	     * The due on a rate figure with a late charge: the greater of the floor in force on the claim's
330	     * date and the figure plus the charge; a correction has no floor. Null for n/a.
331	     */
332	    public static BigDecimal floored(Claim claim, BigDecimal figure, BigDecimal late, Settings settings) {
333	        if (figure == null) return null;
334	        BigDecimal due = figure.add(late);
335	        return claim.isCorrection() ? due : due.max(settings.floorOn(claim.getDate()));
336	    }
337	
338	    /** How the claim's live figures round, by the date it rounds by and the sheet's policy date. */
339	    public static RoundingMode rounding(Claim claim, Settings settings, LocalDate today) {
340	        return settings.rounding(claim.getRoundDate(), today);
341	    }
342	
343	    /**
344	     * The claim's due as the screen shows it: the due fixed when it was settled, else its live due
345	     * ({@link #floored}) on its rate figure ({@link #of}) and the late charge an OPEN or PENDING claim
346	     * gains on that figure while overdue on {@code today}. Null for n/a.
347	     */
348	    public static BigDecimal withLate(Claim claim, List<Rate> rates, String grade, Settings settings,
349	            LocalDate today) {
350	        if (claim.getSettledDue() != null) return claim.getSettledDue();
351	        BigDecimal figure = of(claim, rates, grade, settings, today);
352	        return figure == null ? null : floored(claim, figure, late(claim, figure, grade, settings, today), settings);
353	    }
354	
355	    /**
356	     * The late charge on a figure: for an OPEN or PENDING claim past its due-by (fixed when it was made)
357	     * plus the grace days of its grade ({@code grade}, the one in force on its date) on its date
358	     * ({@link Settings#overdueFrom}) on {@code today}, for every full 30 days it is overdue the
359	     * sheet's late percent in force on that boundary date (that day plus 30, 60, 90 ... days) of the figure plus the
360	     * charges of the boundaries before it (compounding), each rounded to two
361	     * decimals as the claim rounds, added up; else 0.00 (as for a claim deferred on today). Never bound by a statement:
362	     * it follows the sheet's today until the claim is settled.
363	     */
364	    public static BigDecimal late(Claim claim, BigDecimal figure, String grade, Settings settings, LocalDate today) {
365	        if (!claim.isOpen() || claim.isDeferredOn(today)) return BigDecimal.ZERO.setScale(2);
366	        return lateAsOpen(claim, figure, grade, settings, today);
367	    }
368	
369	    /** The late charge on a figure as {@link #late} reads it for an open claim, whatever the claim's status. */
370	    public static BigDecimal lateAsOpen(Claim claim, BigDecimal figure, String grade, Settings settings,
371	            LocalDate today) {
372	        BigDecimal none = BigDecimal.ZERO.setScale(2);
373	        if (figure == null || claim.isCorrection()) return none;
374	        LocalDate from = settings.overdueFrom(claim.getDueBy(), grade, claim.getDate());
375	        long overdue = ChronoUnit.DAYS.between(from, today);
376	        long periods = overdue > 0 ? overdue / 30 : 0;
377	        RoundingMode mode = rounding(claim, settings, today);
378	        BigDecimal charge = none;
379	        for (long k = 1; k <= periods; k++) {
380	            BigDecimal pct = settings.latePctOn(from.plusDays(30 * k));
381	            if (pct.signum() != 0) charge = charge.add(times(figure.add(charge), pct, mode));
382	        }
383	        return charge;
384	    }
385	
386	    /** The amount times the percent, divided by 100 and rounded to two decimals. */
387	    private static BigDecimal times(BigDecimal amount, BigDecimal pct, RoundingMode mode) {
388	        return amount.multiply(pct).divide(BigDecimal.valueOf(100), 2, mode);
389	    }
390	}
