434	package net.officefloor.hq.app.rollup;
435	
436	import java.math.BigDecimal;
437	import java.time.LocalDate;
438	import java.util.ArrayList;
439	import java.util.LinkedHashMap;
440	import java.util.List;
441	import java.util.Map;
442	import net.officefloor.hq.app.claim.Claim;
443	import net.officefloor.hq.app.claim.ClaimFigure;
444	import net.officefloor.hq.app.claim.ClaimRepository;
445	import net.officefloor.hq.app.person.Person;
446	import net.officefloor.hq.app.person.PersonRepository;
447	import net.officefloor.hq.app.rate.Rate;
448	import net.officefloor.hq.app.rate.RateRepository;
449	import net.officefloor.hq.app.setting.Settings;
450	
451	/**
452	 * The sheet's figures as the screen shows them: each person's claimed, due-total and overdue-total (by person id,
453	 * in the order they were added), and the sheet's claimed-total, due-total and overdue-total.
454	 */
455	public record Rollup(Map<Long, Figures> people, String claimedTotal, String dueTotal, String overdueTotal) {
456	
457	    /** A person's figures: their name, claimed, due-total (n/a when none) and overdue-total. */
458	    public record Figures(String name, String claimed, String dueTotal, String overdueTotal) {
459	        boolean sameFigures(Figures other) {
460	            return other != null && claimed.equals(other.claimed) && dueTotal.equals(other.dueTotal)
461	                    && overdueTotal.equals(other.overdueTotal);
462	        }
463	    }
464	
465	    /**
466	     * The sheet's figures now. A person's claimed is the amounts of their claims that count (OPEN
467	     * and SETTLED, but not an unbound OPEN one dated within one of their holds) added up; their due-total the figures of those claims added up, skipping n/a (a live due is the greater of the floor on its date and its rate figure plus the late
468	     * charge it gains on {@code today}), and
469	     * n/a when their grade in force today has no rate today and no claim that counts keeps a fixed
470	     * figure or has one under the grade in force on its date when that is another grade, or
471	     * has one dated on or before today (under a rate that has since ended), held to the sheet's cap. Each claim
472	     * takes the rate of the grade in force on its date. The
473	     * sheet's totals add these up, skipping n/a; with three or more figures, the due-total and
474	     * overdue-total leave out the single highest and the single lowest.
475	     */
476	    public static Rollup of(String sheetId, LocalDate today, PersonRepository people, ClaimRepository claims,
477	            RateRepository rates, Settings settings) {
478	        List<Rate> all = rates.findAll(sheetId);
479	        List<Claim> sheetClaims = claims.findAll(sheetId);
480	        Map<Long, Figures> figures = new LinkedHashMap<>();
481	        BigDecimal claimedTotal = BigDecimal.ZERO.setScale(2);
482	        List<BigDecimal> dues = new ArrayList<>();
483	        List<BigDecimal> overdues = new ArrayList<>();
484	        for (Person person : people.findAll(sheetId)) {
485	            BigDecimal claimed = BigDecimal.ZERO.setScale(2);
486	            BigDecimal due = BigDecimal.ZERO.setScale(2);
487	            BigDecimal overdue = BigDecimal.ZERO.setScale(2);
488	            boolean fixed = false;
489	            for (Claim claim : sheetClaims) {
490	                if (claim.getPersonId() != person.getId()) continue;
491	                if (!claim.counts(person.heldOn(claim.getDate(), today), today)) continue;
492	                claimed = claimed.add(claim.getAmount());
493	                if (claim.getSettledDue() != null || claim.boundDue() != null) fixed = true;
494	                String grade = person.gradeOn(claim.getDate());
495	                BigDecimal figure = ClaimFigure.withLate(claim, all, grade, settings, today);
496	                if (figure != null) due = due.add(figure);
497	                if (figure != null && overdue(claim, grade, settings, today)) overdue = overdue.add(figure);
498	                // A figure found under a grade other than today's is kept, whatever today's rate.
499	                if (figure != null && !grade.equals(person.gradeOn(today))) fixed = true;
500	                // So is one dated on or before today, found under a rate that has since ended.
501	                if (figure != null && !claim.getDate().isAfter(today)) fixed = true;
502	            }
503	            boolean none = Rate.inForce(all, person.gradeOn(today), today).isEmpty() && !fixed;
504	            claimedTotal = claimedTotal.add(claimed);
505	            overdues.add(overdue);
506	            due = settings.capped(due, today);
507	            if (!none) dues.add(due);
508	            figures.put(person.getId(), new Figures(person.getName(), show(claimed), none ? "n/a" : show(due),
509	                    show(overdue)));
510	        }
511	        return new Rollup(figures, show(claimedTotal), show(trimmed(dues)), show(trimmed(overdues)));
512	    }
513	
514	    /** People's figures added up: with three or more, the single highest and single lowest left out. */
515	    private static BigDecimal trimmed(List<BigDecimal> values) {
516	        List<BigDecimal> sorted = new ArrayList<>(values);
517	        sorted.sort(BigDecimal::compareTo);
518	        if (sorted.size() >= 3) sorted = sorted.subList(1, sorted.size() - 1);
519	        return sorted.stream().reduce(BigDecimal.ZERO.setScale(2), BigDecimal::add);
520	    }
521	
522	    /**
523	     * Whether a claim is overdue on {@code today}: open (OPEN or PENDING) and past its due-by plus the
524	     * grace days of its grade on its date ({@link Settings#overdueFrom}).
525	     */
526	    private static boolean overdue(Claim claim, String grade, Settings settings, LocalDate today) {
527	        return claim.isOpen() && today != null && claim.getDueBy() != null
528	                && settings.overdueFrom(claim.getDueBy(), grade, claim.getDate()).isBefore(today);
529	    }
530	
531	    /**
532	     * The audit lines for the move from {@code before} to this: one ROLLUP line per person whose
533	     * figures changed (a person new since counts as changed), then a TOTALS line when any of the
534	     * sheet's three totals changed.
535	     */
536	    public List<String> changesSince(Rollup before, String sheetId, String user) {
537	        List<String> lines = new ArrayList<>();
538	        String head = " sheet=" + sheetId + " by=" + user;
539	        people.forEach((id, now) -> {
540	            if (!now.sameFigures(before.people().get(id))) {
541	                lines.add("ROLLUP" + head + " person=" + now.name() + " claimed=" + now.claimed()
542	                        + " due-total=" + now.dueTotal() + " overdue-total=" + now.overdueTotal());
543	            }
544	        });
545	        if (!claimedTotal.equals(before.claimedTotal()) || !dueTotal.equals(before.dueTotal())
546	                || !overdueTotal.equals(before.overdueTotal())) {
547	            lines.add("TOTALS" + head + " claimed-total=" + claimedTotal + " due-total=" + dueTotal
548	                    + " overdue-total=" + overdueTotal);
549	        }
550	        return lines;
551	    }
552	
553	    private static String show(BigDecimal value) {
554	        return value.setScale(2).toPlainString();
555	    }
556	}
