import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';
import { gradeOn } from '../people/people';
import type { Grade, GradeFrom, Hold } from '../people/people';
import { counts, isBound, isCorrection, isDeferred, isOpen } from '../claims/claims';
import type { Claim } from '../claims/claims';

/**
 * A grade's rate: a percent with two decimals, from a date (yyyy-MM-dd; '' when it applies from the
 * beginning of time) through a date (yyyy-MM-dd; '' when it has no end).
 */
export type Rate = { grade: Grade; pct: string; from: string; to: string };

export const ratesKey = (sheetId: string) => ['sheet', sheetId, 'rates'] as const;

/** The sheet's rates, by grade then from-date (none first). */
export function useRates(sheetId: string) {
  return useQuery({
    queryKey: ratesKey(sheetId),
    queryFn: async () =>
      (await getJson<{ rates: Rate[] }>(`/api/sheets/${encodeURIComponent(sheetId)}/rates`)).rates,
  });
}

/**
 * A grade's rate in force on a date (yyyy-MM-dd): the one whose from-date is the latest on or
 * before it, unless its to-date is before the date. Null when the date is before every rate the
 * grade has (or it has none), or after the to-date of the rate that would apply.
 */
export function rateOn(rates: Rate[], grade: Grade, date: string): string | null {
  let best: Rate | null = null;
  for (const r of rates) {
    if (r.grade !== grade || r.from > date) continue;
    if (best === null || r.from > best.from) best = r;
  }
  if (best === null || (best.to !== '' && best.to < date)) return null;
  return best.pct;
}

/** The sheet's rate for a grade on a date, or null when none is in force (or the rates are not read yet). */
export function useGradeRate(sheetId: string, grade: Grade, date: string): string | null {
  return rateOn(useRates(sheetId).data ?? [], grade, date);
}

/**
 * A dated setting: its starting value, in force before every recorded value, and the values recorded
 * for it, each from a date (yyyy-MM-dd).
 */
export type Dated = { start: string; values: { from: string; value: string }[] };

/** A dated setting's value in force on a date (yyyy-MM-dd): the one with the latest from-date on or before it, else its start. */
export function valueOn(dated: Dated, date: string): string {
  let best: { from: string; value: string } | null = null;
  for (const v of dated.values) {
    if (v.from > date) continue;
    if (best === null || v.from > best.from) best = v;
  }
  return best === null || best.value === '' ? dated.start : best.value;
}

/** A percent as a rate takes it: 0.00 or more, with up to two decimals. */
export const PCT = /^\d+(\.\d{1,2})?$/;

export const NA = 'n/a';

/** A two-decimal number (negative for a correction) as a whole count of hundredths. */
function hundredths(value: string): bigint {
  const trimmed = value.trim();
  const negative = trimmed.startsWith('-');
  const [whole, frac = ''] = (negative ? trimmed.slice(1) : trimmed).split('.');
  const cents = BigInt(whole || '0') * 100n + BigInt((frac + '00').slice(0, 2));
  return negative ? -cents : cents;
}

function showCents(cents: bigint): string {
  const abs = cents < 0n ? -cents : cents;
  return `${cents < 0n ? '-' : ''}${abs / 100n}.${(abs % 100n).toString().padStart(2, '0')}`;
}

/**
 * An amount times a rate, divided by 100, rounded to two decimals (half up when `halfUp`, else half
 * to even), raised to the sheet's `floor` when below it; n/a with no rate (no floor applies to n/a).
 * Worked in whole numbers so no floating-point error creeps in. A correction (a negative amount)
 * takes no floor (`floor` null).
 */
export function due(amount: string, pct: string | null, floor: string | null, halfUp: boolean): string {
  if (pct === null) return NA;
  const rounded = percentOf(amount, pct, 1n, halfUp);
  if (floor === null) return showCents(rounded);
  const least = hundredths(floor);
  return showCents(rounded < least ? least : rounded);
}

/**
 * `times` × a percent of a two-decimal figure, in cents, rounded half up when `halfUp`, else half
 * to even (either symmetric about 0).
 */
function percentOf(figure: string, pct: string, times: bigint, halfUp: boolean): bigint {
  // cents × basis points is the due in millionths of a unit: 10000 of them to the cent.
  const signed = hundredths(figure) * hundredths(pct) * times;
  const x = signed < 0n ? -signed : signed;
  const cents = x / 10000n;
  const rest = x % 10000n;
  const rounded = rest > 5000n || (rest === 5000n && (halfUp || cents % 2n === 1n)) ? cents + 1n : cents;
  return signed < 0n ? -rounded : rounded;
}

/**
 * What the late charge and a claim's rounding need: the sheet's late percent (two decimals, dated: a
 * claim takes the one in force on its date), its
 * today (yyyy-MM-dd; '' until read) and its policy date (yyyy-MM-dd; '' for its
 * today), and each grade's grace days (dated, '' for none: a claim takes those of its grade, the one in
 * force on its date, in force on its date).
 */
export type Late = { pct: Dated; today: string; policyDate: string; grace: Record<string, Dated> };

/**
 * The day a claim's overdue count starts from: its due-by plus the grace days of its `grade` (the one
 * in force on its date) in force on its date, or its due-by when that grade has none. A claim is
 * overdue when this is before the sheet's today, and its late charge's 30-day boundaries are counted
 * from it. Its due-by as shown stays as it is.
 */
export function overdueFrom(claim: Claim, grade: string, late: Late): string {
  const grace = late.grace[grade];
  const days = grace ? valueOn(grace, claim.date) : '';
  return days === '' ? claim.dueBy : addDays(claim.dueBy, Number(days));
}

/**
 * Whether a claim's live figures round half up: it rounds by a date (its own, or for a correction
 * the date of the claim it corrects) before the sheet's policy date (its today when blank); on or
 * after it they round half to even.
 */
export function roundsHalfUp(claim: Claim, late: Late): boolean {
  const policy = late.policyDate !== '' ? late.policyDate : late.today;
  return (claim.roundDate || claim.date) < policy;
}

/** Whole days from one date (yyyy-MM-dd) to another, worked in UTC so no zone shifts it. */
export function daysBetween(from: string, to: string): number {
  const utc = (date: string) => {
    const [y, m, d] = date.split('-').map(Number);
    return Date.UTC(y, m - 1, d);
  };
  return Math.round((utc(to) - utc(from)) / 86_400_000);
}

/** A date (yyyy-MM-dd) some whole days on, worked in UTC so no zone shifts it. */
export function addDays(date: string, days: number): string {
  const [y, m, d] = date.split('-').map(Number);
  return new Date(Date.UTC(y, m - 1, d + days)).toISOString().slice(0, 10);
}

/**
 * A claim's late charge on its `figure`: for an OPEN or PENDING claim past its due-by (fixed when it was
 * made) plus its grade's grace ({@link overdueFrom}) on the sheet's today, for every full 30 days it is
 * overdue the late percent in force on that boundary date (that day plus 30, 60, 90 ... days) of the figure plus the
 * charges of the boundaries before it (compounding), each rounded as the claim rounds, added up; else nothing (as for a claim deferred on the sheet's today). A statement never binds it: it follows the sheet's today.
 */
function lateCharge(claim: Claim, figure: string, late: Late, grade: string): bigint {
  if (!isOpen(claim) || isDeferred(claim, late.today) || figure === NA || late.today === '' || isCorrection(claim)) return 0n;
  const from = overdueFrom(claim, grade, late);
  const overdue = daysBetween(from, late.today);
  const periods = overdue > 0 ? Math.floor(overdue / 30) : 0;
  const halfUp = roundsHalfUp(claim, late);
  let charge = 0n;
  for (let k = 1; k <= periods; k++) {
    const pct = valueOn(late.pct, addDays(from, 30 * k));
    if (hundredths(pct) !== 0n) charge += percentOf(showCents(hundredths(figure) + charge), pct, 1n, halfUp);
  }
  return charge;
}

/** Due values added up, skipping n/a. */
export function sumDue(values: string[]): string {
  return showCents(values.filter((v) => v !== NA).reduce((n, v) => n + hundredths(v), 0n));
}

/**
 * People's figures added up as a sheet's total, skipping n/a: with three or more figures, the single
 * highest and the single lowest are left out.
 */
export function trimmedSumDue(values: string[]): string {
  const figures = values.filter((v) => v !== NA).map(hundredths).sort((a, b) => (a < b ? -1 : a > b ? 1 : 0));
  const kept = figures.length >= 3 ? figures.slice(1, -1) : figures;
  return showCents(kept.reduce((n, v) => n + v, 0n));
}

/**
 * A claim's due: the one fixed when it was settled (its late charge frozen in), else its live due:
 * the greater of the sheet's `floor` in force on its date and its figure (the one its person's last
 * statement bound it to, never while it is PENDING, else its amount at the rate in force on its date)
 * plus the late charge an overdue claim gains on that figure (by the grace of its `grade`, the one in
 * force on its date). A correction takes no floor; n/a stays n/a.
 */
export function claimDue(claim: Claim, pct: string | null, floor: Dated, late: Late, grade: string): string {
  if (claim.due !== '') return claim.due;
  const figure = isBound(claim) ? claim.statedDue : due(claim.amount, pct, null, roundsHalfUp(claim, late));
  if (figure === NA) return figure;
  const total = hundredths(figure) + lateCharge(claim, figure, late, grade);
  if (isCorrection(claim)) return showCents(total);
  const least = hundredths(valueOn(floor, claim.date));
  return showCents(total < least ? least : total);
}

/**
 * A person's due-total: the figures of their claims that count (an unbound OPEN one not when dated within one of their `holds`) (each at the rate in force on its
 * date for their grade in force on its date), added up, skipping n/a. With no rate for their grade
 * today it is n/a, unless a claim that counts keeps a fixed figure (settled, or bound by a
 * statement), has a figure under another grade in force on its date, or has a figure dated on or
 * before today (under a rate that has since ended). Held to the sheet's `cap` ('' for none); n/a is
 * not capped.
 */
export function personDueTotal(
  rates: Rate[],
  grades: GradeFrom[],
  today: string,
  claims: Claim[],
  holds: Hold[],
  floor: Dated,
  late: Late,
  cap: string,
): string {
  const total = uncappedDueTotal(rates, grades, today, claims, holds, floor, late);
  if (total === NA || cap === '' || hundredths(total) <= hundredths(cap)) return total;
  return showCents(hundredths(cap));
}

/** How far a person's due-total, before the sheet's `cap` ('' for none), goes above it: 0.00 when it does not. */
export function personExcess(
  rates: Rate[],
  grades: GradeFrom[],
  today: string,
  claims: Claim[],
  holds: Hold[],
  floor: Dated,
  late: Late,
  cap: string,
): string {
  const total = uncappedDueTotal(rates, grades, today, claims, holds, floor, late);
  if (total === NA || cap === '' || hundredths(total) <= hundredths(cap)) return '0.00';
  return showCents(hundredths(total) - hundredths(cap));
}

function uncappedDueTotal(
  rates: Rate[],
  grades: GradeFrom[],
  today: string,
  claims: Claim[],
  holds: Hold[],
  floor: Dated,
  late: Late,
): string {
  const counted = claims.filter((c) => counts(c, holds, today));
  const grade = gradeOn(grades, today);
  const kept = (c: Claim) => c.due !== '' || (isBound(c) && c.statedDue !== NA)
    || (gradeOn(grades, c.date) !== grade && rateOn(rates, gradeOn(grades, c.date), c.date) !== null)
    || (c.date <= today && rateOn(rates, gradeOn(grades, c.date), c.date) !== null);
  if (rateOn(rates, grade, today) === null && !counted.some(kept)) return NA;
  return sumDue(counted.map((c) => claimDue(c, rateOn(rates, gradeOn(grades, c.date), c.date), floor, late, gradeOn(grades, c.date))));
}


/**
 * A person's due-total split by status, before the sheet's cap: their settled-total (the dues of
 * their SETTLED claims that count, at their frozen figures, corrections included) and their
 * open-total (the dues of their OPEN and PENDING claims that count), each added up, skipping n/a.
 */
export function personSplitTotals(
  rates: Rate[],
  grades: GradeFrom[],
  today: string,
  claims: Claim[],
  holds: Hold[],
  floor: Dated,
  late: Late,
): { settled: string; open: string } {
  const counted = claims.filter((c) => counts(c, holds, today));
  const dueOf = (c: Claim) => claimDue(c, rateOn(rates, gradeOn(grades, c.date), c.date), floor, late, gradeOn(grades, c.date));
  return {
    settled: sumDue(counted.filter((c) => c.status === 'SETTLED').map(dueOf)),
    open: sumDue(counted.filter(isOpen).map(dueOf)),
  };
}
import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';
import { heldOn } from '../people/people';
import type { Hold } from '../people/people';

/**
 * A claim's status: DRAFT when made, then OPEN, then SETTLED; a clerk's settle above the clerk
 * limit makes it PENDING until a steward approves it (SETTLED) or rejects it (OPEN again). A DRAFT,
 * OPEN or PENDING claim may be VOID; a SETTLED one too, by a steward within 7 days of its settlement.
 */
export type ClaimStatus = 'DRAFT' | 'OPEN' | 'PENDING' | 'SETTLED' | 'VOID';

/**
 * A claim: its amount with two decimals, its date (yyyy-MM-dd), its note, its status and its
 * number on the sheet (given when it is opened; '' for a draft or a voided claim), and its due as
 * fixed when it was settled ('' while its due is live: unsettled, or settled with no rate), and
 * who opened it ('' until it is opened); whether its person's last statement bound it, and the
 * figure it was bound to ('' when not stated; n/a when it had none); and, for a correction (a
 * negative amount), the number of the settled claim it corrects ('' for any other claim); and the
 * date (yyyy-MM-dd) its figures round by (a correction's is the date of the claim it corrects).
 */
export type Claim = {
  id: string;
  personId: string;
  amount: string;
  date: string;
  note: string;
  status: ClaimStatus;
  number: string;
  due: string;
  openedBy: string;
  stated: boolean;
  statedDue: string;
  corrects: string;
  roundDate: string;
  /** Its due-by (yyyy-MM-dd), fixed when it was made: the terms-th business day after its date (skipping weekends and the sheet's holidays then), its terms its person's own, else its grade's then. */
  dueBy: string;
  /**
   * Its status log, oldest first: one line per status it has had, as
   * `<STATUS> by <user> on <date> due=<due>` (the sheet's today and its due at that moment).
   */
  log: string[];
  /** The date (yyyy-MM-dd) it is deferred until; '' when it was never deferred. */
  deferredUntil: string;
  /** How many proofs it has had added. */
  proofs: number;
  /** The number of the claim it was split off; '' when it was not split off one. */
  splitFrom: string;
  /** The user whose open editor locks it on the sheet's today; '' when no one's does. */
  lockedBy: string;
  /** Whether it was added while its period was soft-closed. */
  lateEntry: boolean;
  /** The last sheet's today (yyyy-MM-dd) a reminder was written for it; '' when it was never reminded. */
  remindedOn: string;
  /** Its external reference, unique on the sheet regardless of case; '' when it has none. */
  ref: string;
  /** Its tags: trimmed, lower-cased, without repeats, sorted; empty when it has none. */
  tags: string[];
  /** The reason it was voided with, from the sheet's list; '' when none. */
  voidReason: string;
  /** Its comments, oldest first, as `<user> on <date>: <text>` (the sheet's today when written). */
  comments: string[];
  /** The number of the bulk settle batch that settled it; '' when none did (settled one at a time, or not settled). */
  batch: string;
};

/** Whether a claim is a correction: it has no floor and no late charge. */
export const isCorrection = (c: Claim) => c.corrects !== '';

/** Whether a claim is open: OPEN, or PENDING a steward's approval. */
export const isOpen = (c: Claim) => c.status === 'OPEN' || c.status === 'PENDING';

/**
 * Whether a claim's stated figure is in force: its person's last statement bound it and it is not
 * PENDING (a PENDING claim shows its live figure).
 */
export const isBound = (c: Claim) => c.stated && c.status !== 'PENDING';

/**
 * Whether a claim is deferred on the sheet's `today`: OPEN and deferred until a date after today.
 * From that date on it is an OPEN claim like any other.
 */
export const isDeferred = (c: Claim, today: string) =>
  c.status === 'OPEN' && c.deferredUntil !== '' && today !== '' && today < c.deferredUntil;

/**
 * Whether a claim counts toward claimed, due-total and every total: only OPEN, PENDING and SETTLED
 * do, and an OPEN or PENDING one not when it is dated within one of its person's `holds`, unless a
 * statement binds it; never one deferred on `today`.
 */
export const counts = (c: Claim, holds: Hold[], today: string) =>
  !isDeferred(c, today) && (c.status === 'SETTLED' || (isOpen(c) && (isBound(c) || !heldOn(holds, c.date))));

/**
 * A claim's status at the end of `day` (yyyy-MM-dd), as its log records it: the status of its last
 * line dated on or before it; null when it had none then (it was added after).
 */
export function statusOn(c: Claim, day: string): ClaimStatus | null {
  let status: ClaimStatus | null = null;
  for (const line of c.log) {
    const m = /^(\w+) by .* on (\d{4}-\d{2}-\d{2}) due=\S*$/.exec(line);
    if (m && m[2] <= day) status = m[1] as ClaimStatus;
  }
  return status;
}

/**
 * Whether a claim counted at the end of `day`: as `counts`, with the status its log records then
 * (never when it was added after), its statement binding and deferral as they are on `today`.
 */
export const countedOn = (c: Claim, day: string, holds: Hold[], today: string) => {
  const status = statusOn(c, day);
  if (status === null || isDeferred(c, today)) return false;
  return status === 'SETTLED' || ((status === 'OPEN' || status === 'PENDING') && (isBound(c) || !heldOn(holds, c.date)));
};

export const claimsKey = (sheetId: string) => ['sheet', sheetId, 'claims'] as const;

export const claimsQuery = (sheetId: string) => ({
  queryKey: claimsKey(sheetId),
  queryFn: async () =>
    (await getJson<{ claims: Claim[] }>(`/api/sheets/${encodeURIComponent(sheetId)}/claims`)).claims,
});

export const tagsKey = (sheetId: string) => [...claimsKey(sheetId), 'tags'] as const;

/** Every tag ever used on the sheet, sorted (re-read whenever its claims are). */
export function useTagsUsed(sheetId: string) {
  return useQuery({
    queryKey: tagsKey(sheetId),
    queryFn: async () =>
      (await getJson<{ tags: string[] }>(`/api/sheets/${encodeURIComponent(sheetId)}/claims`)).tags,
  });
}

export const lastBatchKey = (sheetId: string) => [...claimsKey(sheetId), 'last-batch'] as const;

/** The number of the sheet's last bulk settle batch; '' when there has been none (re-read whenever its claims are). */
export function useLastBatch(sheetId: string) {
  return useQuery({
    queryKey: lastBatchKey(sheetId),
    queryFn: async () =>
      (await getJson<{ lastBatch: string }>(`/api/sheets/${encodeURIComponent(sheetId)}/claims`)).lastBatch,
  });
}

/** The sheet's claims, newest first. */
export function useClaims(sheetId: string) {
  return useQuery(claimsQuery(sheetId));
}

/** An amount as a claim takes it: 0.00 or more, with up to two decimals. */
export const AMOUNT = /^\d+(\.\d{1,2})?$/;

/** An amount as the claim form takes it: up to two decimals, negative for a correction. */
export const CLAIM_AMOUNT = /^-?\d+(\.\d{1,2})?$/;

/**
 * A claim number, as a correction names the claim it corrects: a sheet-wide number, or a number
 * within a period (<period name>-<n>, X-<n> for a claim in no period).
 */
export const CLAIM_NUMBER = /^(\d+|.+-\d+)$/;

/**
 * The amounts of the claims that count (OPEN, PENDING and SETTLED, but not unbound open ones dated within
 * a hold of their person: `holds` tells by person id, nor ones deferred on `today`) added up, in whole cents so no rounding creeps in, shown with two
 * decimals.
 */
export function sumAmounts(claims: Claim[], holds: (personId: string) => Hold[], today: string): string {
  const cents = claims.filter((c) => counts(c, holds(c.personId), today)).reduce((n, c) => n + Math.round(Number(c.amount) * 100), 0);
  return (cents / 100).toFixed(2);
}

