import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';
import { asFlag, useSearchParam } from '../../url/useSearchParam';

export type Grade = 'A' | 'B' | 'C';
export const GRADES: Grade[] = ['A', 'B', 'C'];

/** A grade in force from a date (yyyy-MM-dd; '' from the beginning of time) until the next one. */
export type GradeFrom = { from: string; grade: Grade };

/** The grade in force on a date (yyyy-MM-dd): the one whose from-date is the latest on or before it. */
export function gradeOn(grades: GradeFrom[], date: string): Grade {
  let best = grades[0];
  for (const g of grades) if (g.from <= date && g.from >= best.from) best = g;
  return best.grade;
}

// `version` is raised by each save; an edit sends the version it was made from. `statementCount`
// is how many statements have been taken for them; `statedTotal` and `statementDate` are the last
// one's due-total and date ('' before the first). `retired` is set once they have a retirement
// date, `retiredFrom` ('' when not retired), whatever that date is. `held` is whether they have any hold; `holds` their holds in the order added (see `Hold`).
// `patronIds` are the ids of the people they name as their patrons. `grade` is the grade in force on
// the sheet's today; `grades` every grade they have been given, by from-date, the first from ''.
// `terms` are their own terms in days, ahead of their grade's and the sheet's ('' for none).
// `contact` is their contact, trimmed and lower-cased ('' for none); no two people on a sheet share one.
export type Person = {
  id: string;
  name: string;
  grade: Grade;
  version: number;
  statementCount: number;
  statedTotal: string;
  statementDate: string;
  retired: boolean;
  retiredFrom: string;
  held: boolean;
  holds: Hold[];
  patronIds: string[];
  grades: GradeFrom[];
  terms: string;
  contact: string;
};

/**
 * A hold on a person: from a date to a date (yyyy-MM-dd; `to` '' when open-ended), both inclusive.
 * An OPEN or PENDING claim of theirs dated within one, unless a statement binds it, counts in no total.
 */
export type Hold = { from: string; to: string };

/** Whether the date (yyyy-MM-dd) is within one of the holds. */
export const heldOn = (holds: Hold[], date: string) =>
  holds.some((h) => h.from <= date && (h.to === '' || date <= h.to));

/**
 * The holds a person's claims count against on the sheet's `today`: their own, and from the day
 * their retirement date is reached (`today` on or after it) one covering every date — their OPEN
 * and PENDING claims, unless a statement binds them, then count in no total.
 */
export const liveHolds = (p: Pick<Person, 'holds' | 'retiredFrom'>, today: string): Hold[] =>
  p.retiredFrom !== '' && today !== '' && p.retiredFrom <= today ? [...p.holds, { from: '', to: '' }] : p.holds;

export const peopleKey = (sheetId: string) => ['sheet', sheetId, 'people'] as const;

export const peopleQuery = (sheetId: string) => ({
  queryKey: peopleKey(sheetId),
  queryFn: async () =>
    (await getJson<{ people: Person[] }>(`/api/sheets/${encodeURIComponent(sheetId)}/people`)).people,
});

/** The sheet's people, in the order they were added. */
export function usePeople(sheetId: string) {
  return useQuery(peopleQuery(sheetId));
}

/** Whether retired people are listed. Off when the screen is first opened; loading a sheet keeps it. */
export const useShowRetired = () => useSearchParam('retired', asFlag);
import { gradeOn } from '../people/people';
import type { GradeFrom, Hold } from '../people/people';
import { counts, isDeferred, isOpen } from '../claims/claims';
import type { Claim } from '../claims/claims';
import { claimDue, overdueFrom, rateOn, sumDue } from '../rates/rates';
import type { Dated, Late, Rate } from '../rates/rates';

/** A claim's due-by: fixed when it was made, the terms-th business day after its date, from its person's own terms, else its grade's terms then. */
export const dueBy = (claim: Claim): string => claim.dueBy;

/**
 * Whether a claim is overdue: open (OPEN or PENDING), not deferred, and its due-by plus the grace of
 * its `grade` (the one in force on its date) before the sheet's `today`.
 */
export const isOverdue = (claim: Claim, today: string, late: Late, grade: string): boolean =>
  isOpen(claim) && !isDeferred(claim, today) && today !== '' && overdueFrom(claim, grade, late) < today;

/**
 * A person's overdue claims that count (not an unbound OPEN one dated within one of their `holds`, as it then counts in
 * no total): how many, and their due figures (with their late charge) added up, skipping n/a.
 */
export function personOverdue(
  rates: Rate[],
  grades: GradeFrom[],
  today: string,
  claims: Claim[],
  holds: Hold[],
  floor: Dated,
  late: Late,
): { count: number; total: string } {
  const overdue = claims.filter((c) => counts(c, holds, today) && isOverdue(c, today, late, gradeOn(grades, c.date)));
  return {
    count: overdue.length,
    total: sumDue(overdue.map((c) => claimDue(c, rateOn(rates, gradeOn(grades, c.date), c.date), floor, late, gradeOn(grades, c.date)))),
  };
}
import { gradeOn } from '../people/people';
import type { GradeFrom, Hold } from '../people/people';
import { counts, isOpen } from '../claims/claims';
import type { Claim } from '../claims/claims';
import { claimDue, daysBetween, rateOn, sumDue } from '../rates/rates';
import type { Dated, Late, Rate } from '../rates/rates';

/** A person's due split by claim age: aged 0 to 30 days, 31 to 60, and 61 or more. */
export type Aged = { upTo30: string; upTo60: string; over60: string };

/**
 * A person's open (OPEN or PENDING) claims that count (not an unbound one dated within one of their
 * `holds`, nor one deferred on `today`), their due figures (with their late charge) added up, skipping
 * n/a, split by the claim's age on the sheet's `today`: the days from its date. A claim dated after
 * today is aged 0 to 30.
 */
export function personAged(
  rates: Rate[],
  grades: GradeFrom[],
  today: string,
  claims: Claim[],
  holds: Hold[],
  floor: Dated,
  late: Late,
): Aged {
  const open = claims.filter((c) => isOpen(c) && counts(c, holds, today));
  const age = (c: Claim) => (today === '' ? 0 : daysBetween(c.date, today));
  const sum = (bucket: Claim[]) =>
    sumDue(bucket.map((c) => claimDue(c, rateOn(rates, gradeOn(grades, c.date), c.date), floor, late, gradeOn(grades, c.date))));
  return {
    upTo30: sum(open.filter((c) => age(c) <= 30)),
    upTo60: sum(open.filter((c) => age(c) > 30 && age(c) <= 60)),
    over60: sum(open.filter((c) => age(c) > 60)),
  };
}
import { SheetBody } from '../../slots/defs/sheetBody';
import { liveHolds, usePeople } from '../people/people';
import { useSheetToday } from '../sheet/sheet';
import { sumAmounts, useClaims } from './claims';

// The sheet's claimed-total: everyone's claims added up.
function ClaimedTotal({ sheetId }: { sheetId: string }) {
  const claims = useClaims(sheetId);
  const today = useSheetToday(sheetId);
  const holds = new Map((usePeople(sheetId).data ?? []).map((p) => [p.id, liveHolds(p, today)]));
  return (
    <p>
      Claimed in all: <strong data-testid="rollup-claimed-total">{sumAmounts(claims.data ?? [], (id) => holds.get(id) ?? [], today)}</strong>
    </p>
  );
}

export const contribution = SheetBody.fill({ order: 10, Component: ClaimedTotal });
import { SheetBody } from '../../slots/defs/sheetBody';
import { useClaims } from '../claims/claims';
import type { ClaimStatus } from '../claims/claims';
import { GRADES, liveHolds, usePeople } from '../people/people';
import type { Person } from '../people/people';
import { personDueTotal, sumDue, useRates } from '../rates/rates';
import { useCap, useFloor, useLate } from '../access/access';
import { useSheetToday } from '../sheet/sheet';
import { periodDueTotal, usePeriods } from '../periods/periods';
import { isActive } from '../active/active';
import { useVoidReasons } from '../voidreasons/voidReasons';

// Every status the summary counts.
const STATUSES: ClaimStatus[] = ['DRAFT', 'OPEN', 'PENDING', 'SETTLED', 'VOID'];

// The sheet's summary, worked from the same figures as the lists: per grade, the people on it today
// (retired people left out), their due-totals added up and how many of them are active; per
// period, its due-total; per status, how many claims have it; per void reason on the list, how many
// VOID claims were voided with it.
function Summary({ sheetId }: { sheetId: string }) {
  const people = usePeople(sheetId).data ?? [];
  const claims = useClaims(sheetId).data ?? [];
  const rates = useRates(sheetId).data ?? [];
  const periods = usePeriods(sheetId).data ?? [];
  const today = useSheetToday(sheetId);
  const floor = useFloor(sheetId);
  const late = useLate(sheetId);
  const cap = useCap(sheetId);
  const voidReasons = useVoidReasons(sheetId).data ?? [];

  const active = people.filter((p) => !p.retired);
  const claimsOf = (p: Person) => claims.filter((c) => c.personId === p.id);
  const dueOf = (p: Person) => personDueTotal(rates, p.grades, today, claimsOf(p), liveHolds(p, today), floor, late, cap);

  return (
    <section data-testid="summary">
      <h2>Summary</h2>
      <table>
        <thead>
          <tr>
            <th>Grade</th>
            <th>People</th>
            <th>Due</th>
            <th>Active</th>
          </tr>
        </thead>
        <tbody>
          {GRADES.map((g) => {
            const onGrade = active.filter((p) => p.grade === g);
            return (
              <tr key={g}>
                <td>{g}</td>
                <td data-testid={`summary-grade-${g}-count`}>{onGrade.length}</td>
                <td data-testid={`summary-grade-${g}-due-total`}>{sumDue(onGrade.map(dueOf))}</td>
                <td data-testid={`summary-grade-${g}-active`}>
                  {onGrade.filter((p) => isActive(claimsOf(p), liveHolds(p, today), today)).length}
                </td>
              </tr>
            );
          })}
        </tbody>
      </table>
      <table>
        <thead>
          <tr>
            <th>Period</th>
            <th>Due</th>
          </tr>
        </thead>
        <tbody>
          {periods.map((p) => (
            <tr key={p.name}>
              <td>{p.name}</td>
              <td data-testid={`summary-period-${p.name}-due-total`}>
                {periodDueTotal(p, people, claims, rates, floor, late)}
              </td>
            </tr>
          ))}
        </tbody>
      </table>
      <table>
        <thead>
          <tr>
            <th>Status</th>
            <th>Claims</th>
          </tr>
        </thead>
        <tbody>
          {STATUSES.map((s) => (
            <tr key={s}>
              <td>{s}</td>
              <td data-testid={`summary-status-${s}-count`}>{claims.filter((c) => c.status === s).length}</td>
            </tr>
          ))}
        </tbody>
      </table>
      <table>
        <thead>
          <tr>
            <th>Void reason</th>
            <th>Claims</th>
          </tr>
        </thead>
        <tbody>
          {voidReasons.map(({ reason }) => (
            <tr key={reason}>
              <td>{reason}</td>
              <td data-testid={`summary-void-${reason}-count`}>
                {claims.filter((c) => c.status === 'VOID' && c.voidReason === reason).length}
              </td>
            </tr>
          ))}
        </tbody>
      </table>
    </section>
  );
}

export const contribution = SheetBody.fill({ order: 30, Component: Summary });
import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';
import { countedOn } from '../claims/claims';
import type { Claim } from '../claims/claims';
import { gradeOn, liveHolds } from '../people/people';
import type { Person } from '../people/people';
import { claimDue, rateOn, sumDue } from '../rates/rates';
import type { Dated, Late, Rate } from '../rates/rates';

/**
 * A period: its name (unique on the sheet), its from and to dates (yyyy-MM-dd), inclusive, whether
 * it is closed, the due-total fixed when it was closed ('' while open), and each person's due-total
 * fixed when it was closed, by person id (empty while open), and whether it is soft-closed: closed
 * with its figures fixed, but its claims can still be changed.
 */
export type Period = {
  name: string;
  from: string;
  to: string;
  closed: boolean;
  closedTotal: string;
  personTotals: Record<string, string>;
  soft: boolean;
};

export const periodsKey = (sheetId: string) => ['sheet', sheetId, 'periods'] as const;

/** The sheet's periods, by from-date. */
export function usePeriods(sheetId: string) {
  return useQuery({
    queryKey: periodsKey(sheetId),
    queryFn: async () =>
      (await getJson<{ periods: Period[] }>(`/api/sheets/${encodeURIComponent(sheetId)}/periods`)).periods,
  });
}

/** The period whose dates contain the date (yyyy-MM-dd), or null when none does. */
export function periodOf(periods: Period[], date: string): Period | null {
  return periods.find((p) => p.from <= date && date <= p.to) ?? null;
}

/**
 * A person's due-total for a period: the one fixed when it was closed (0.00 for a person added
 * after), else the due as shown now of their claims due by a date in it (a claim's period is the one
 * containing its due-by) that counted at the end of its last
 * day, by the status their log records then, added up.
 */
export function personPeriodDueTotal(
  period: Period,
  person: Person,
  claims: Claim[],
  rates: Rate[],
  floor: Dated,
  late: Late,
): string {
  if (period.closed) return period.personTotals[person.id] ?? '0.00';
  return sumDue(
    claims
      .filter((c) => c.personId === person.id && countedOn(c, period.to, liveHolds(person, late.today), late.today) && period.from <= c.dueBy && c.dueBy <= period.to)
      .map((c) => claimDue(c, rateOn(rates, gradeOn(person.grades, c.date), c.date), floor, late, gradeOn(person.grades, c.date))),
  );
}

/** A period's due-total: the people's due-totals for it, added up. */
export function periodDueTotal(
  period: Period,
  people: Person[],
  claims: Claim[],
  rates: Rate[],
  floor: Dated,
  late: Late,
): string {
  return sumDue(people.map((person) => personPeriodDueTotal(period, person, claims, rates, floor, late)));
}
import type { Hold } from '../people/people';
import { counts, isOpen } from '../claims/claims';
import type { Claim } from '../claims/claims';
import { addDays } from '../rates/rates';

/** How many days back from the sheet's today (today included) a claim keeps its person active. */
export const ACTIVE_DAYS = 30;

/**
 * Whether a person is active: they have an open (OPEN or PENDING) claim that counts, dated within
 * the 30 days up to and including the sheet's `today`.
 */
export function isActive(claims: Claim[], holds: Hold[], today: string): boolean {
  if (today === '') return false;
  const since = addDays(today, -(ACTIVE_DAYS - 1));
  return claims.some((c) => isOpen(c) && counts(c, holds, today) && c.date >= since && c.date <= today);
}
import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';

export type Sheet = { id: string; today: string; archived: boolean };

export const sheetKey = (sheetId: string) => ['sheet', sheetId, 'info'] as const;

/** The loaded sheet: its id, its today (yyyy-MM-dd) and whether a steward has archived it. */
export function useSheet(sheetId: string) {
  return useQuery({
    queryKey: sheetKey(sheetId),
    queryFn: () => getJson<Sheet>(`/api/sheets/${encodeURIComponent(sheetId)}`),
  });
