/** A note threshold as the screen takes it: blank, or 0.00 or more with up to two decimals. */
export const NOTE_THRESHOLD = /^\d+(\.\d{1,2})?$/;

/** A floor as the screen takes it: 0.00 or more with up to two decimals. */
