/**
 * Settles the claim and fixes its due: its amount times the rate of its person's grade in force on its date, in force on the
 * claim's date, divided by 100 and rounded to two decimals as the claim rounds (by the sheet's policy date), or
 * for a claim a statement bound its bound figure; with the late charge it has gained on that figure
 * by the sheet's today frozen in on top, and at least the floor in force on its date (applied last).
 * With no such rate the due is not fixed. The user who opened the claim, or last edited it, may not settle it.
 * When a clerk (any user not made a steward) settles a claim whose due is above the sheet's clerk
 * limit, it goes to PENDING instead, its due left live until a steward approves or rejects it; a
 * due of n/a is within any limit. Before the clerk limit is considered, a claim whose due is above
 * the proof threshold in force on its date is refused while it has no proofs. Only a role the
 * permission matrix allows may settle.
 */
public class SettleClaim {
    public void apply(@Val Sheet sheet, @Val Claim claim, PersonRepository people, RateRepository rates,
            RoleRepository roles, SettingsRepository settingsStore, HttpServletRequest request)
            throws InvalidClaimStatusException, SelfSettleException {
        settle(sheet, claim, Audit.user(request), people, rates, roles, settingsStore);
        claim.setSettleBatch(null); // settled one at a time: in no batch
    }
    /** Settles the claim as the given user would, by the rules above; throws when it may not. */
    static void settle(Sheet sheet, Claim claim, String user, PersonRepository people, RateRepository rates,
            RoleRepository roles, SettingsRepository settingsStore)
            throws InvalidClaimStatusException, SelfSettleException {
        Person person = people.find(sheet.id(), claim.getPersonId());
        Settings settings = settingsStore.find(sheet.id());
        String role = roles.roleOf(sheet.id(), user);
        if (!settings.allows("settle", role)) {
            throw new InvalidClaimStatusException("A " + role + " may not settle a claim");
        }
        String grade = person.gradeOn(claim.getDate());
        BigDecimal figure = claim.isStated() ? claim.getStatedDue()
                : ClaimFigure.live(claim, rates.findAll(sheet.id()), grade, settings, sheet.today());
        // The late charge is read while the claim is still OPEN.
        BigDecimal late = ClaimFigure.late(claim, figure, grade, settings, sheet.today());
        if (claim.isDeferredOn(sheet.today())) {
            throw new InvalidClaimStatusException("A claim deferred until " + claim.getDeferredUntil() + " cannot be settled");
        }
        if (!claim.getStatus().canMoveTo(ClaimStatus.SETTLED)) {
            throw new InvalidClaimStatusException(claim.getStatus(), ClaimStatus.SETTLED);
        }
        if (user.equals(claim.getOpenedBy())) throw new SelfSettleException(user);
        if (claim.isOwnedBy(user)) throw new SelfSettleException(user, "last edited");
        BigDecimal due = ClaimFigure.floored(claim, figure, late, settings);
        if (settings.needsProof(due, grade, claim.getDate(), claim.getProofs())) throw new InvalidClaimStatusException(ProofRequired.MESSAGE);
        if (!settings.withinClerkLimit(due, sheet.today()) && Role.CLERK.equals(role)) {
            claim.moveTo(ClaimStatus.PENDING);
            return;
        }
        claim.moveTo(ClaimStatus.SETTLED);
        claim.setSettledDue(due);
    }
}
=== claim/ApproveClaim.java
/**
 * Approves a PENDING claim: it is settled, its due fixed at this moment at its live figure (a
 * PENDING claim is bound by no statement) with the late charge it has gained by the sheet's today.
 * Only a steward may approve it, and not the user who opened it or last edited it; and not while it has no proofs
 * when its due is above the proof threshold in force on its date.
 */
public class ApproveClaim {
    public void apply(@Val Sheet sheet, @Val Claim claim, PersonRepository people, RateRepository rates,
            RoleRepository roles, SettingsRepository settings, HttpServletRequest request)
            throws InvalidClaimStatusException, ApprovalException {
        if (claim.getStatus() != ClaimStatus.PENDING) {
            throw new InvalidClaimStatusException(claim.getStatus(), ClaimStatus.SETTLED);
        }
        String user = Audit.user(request);
        if (!Role.STEWARD.equals(roles.roleOf(sheet.id(), user))) {
            throw new ApprovalException("Only a steward may approve a claim: " + user + " is a clerk");
        }
        if (user.equals(claim.getOpenedBy())) {
            throw new ApprovalException("A claim cannot be approved by " + user + ", who opened it");
        }
        if (claim.isOwnedBy(user)) {
            throw new ApprovalException("A claim cannot be approved by " + user + ", who last edited it");
        }
        Person person = people.find(sheet.id(), claim.getPersonId());
        Settings sheetSettings = settings.find(sheet.id());
        // Read while the claim is still PENDING: its live figure and its late charge.
        java.math.BigDecimal due = ClaimFigure.withLate(claim, rates.findAll(sheet.id()), person.gradeOn(claim.getDate()),
                sheetSettings, sheet.today());
        if (sheetSettings.needsProof(due, person.gradeOn(claim.getDate()), claim.getDate(), claim.getProofs())) {
            throw new InvalidClaimStatusException(ProofRequired.MESSAGE);
        }
        claim.approve(due);
    }
}
=== claim/VoidClaim.java
/**
 * Voids the claim. Only a role the permission matrix allows may void. A SETTLED claim may be
 * voided only by a steward, and only within {@link #SETTLED_DAYS} days of its settlement (its
 * status log's SETTLED date) by the sheet's today; it keeps its number and its frozen figure,
 * which leaves every total. While the sheet has void reasons, a void needs one of them, kept on
 * the claim.
 */
public class VoidClaim {
    /** How many days after its settlement a SETTLED claim may still be voided. */
    static final long SETTLED_DAYS = 7;
    public void apply(@Val Sheet sheet, @Val Claim claim, @Val VoidRequest body, RoleRepository roles,
            SettingsRepository settings, ClaimLogRepository log, VoidReasonRepository reasons,
            HttpServletRequest request) throws InvalidClaimStatusException, InvalidClaimException {
        String user = Audit.user(request);
        String role = roles.roleOf(sheet.id(), user);
        if (!settings.find(sheet.id()).allows("void", role)) {
            throw new InvalidClaimStatusException("A " + role + " may not void a claim");
        }
        if (claim.getStatus() == ClaimStatus.SETTLED) {
            if (!Role.STEWARD.equals(role)) {
                throw new InvalidClaimStatusException("Only a steward may void a SETTLED claim: " + user + " is a " + role);
            }
            LocalDate settled = log.settledOn(claim);
            long days = settled == null ? -1 : ChronoUnit.DAYS.between(settled, sheet.today());
            if (days < 0 || days > SETTLED_DAYS) {
                throw new InvalidClaimStatusException("A SETTLED claim may be voided only within " + SETTLED_DAYS
                        + " days of its settlement" + (settled == null ? "" : " on " + settled));
            }
        }
        java.util.List<String> listed = reasons.findAll(sheet.id()).stream().map(VoidReason::reason).toList();
        String reason = body.reason();
        if (!listed.isEmpty()) {
            if (reason == null) throw new InvalidClaimException("A void needs a reason from the sheet's list");
            if (!listed.contains(reason)) throw new InvalidClaimException(reason + " is not on the sheet's void reasons");
        } else if (reason != null) {
            throw new InvalidClaimException("The sheet has no void reasons: " + reason + " is not one");
        }
        claim.moveTo(ClaimStatus.VOID);
        claim.setVoidReason(reason);
    }
}
=== claim/ResettleClaim.java
/**
 * Re-settles a SETTLED claim: its due is fixed again at the figure it would have today as an OPEN
 * claim bound by no statement: its live rate figure (today's rates and grades) with the late
 * charge it would have gained on it by the sheet's today, then at least the floor on its date. Only a steward may re-settle a claim.
 */
public class ResettleClaim {
    public void apply(@Val Sheet sheet, @Val Claim claim, PersonRepository people, RateRepository rates,
            RoleRepository roles, SettingsRepository settingsStore, HttpServletRequest request,
            Out<Resettlement> resettlement) throws InvalidClaimStatusException, ResettleException {
        if (claim.getStatus() != ClaimStatus.SETTLED) {
            throw new InvalidClaimStatusException("Only a SETTLED claim can be re-settled: this one is " + claim.getStatus());
        }
        String user = Audit.user(request);
        if (!Role.STEWARD.equals(roles.roleOf(sheet.id(), user))) {
            throw new ResettleException("Only a steward may re-settle a claim: " + user + " is a clerk");
        }
        Person person = people.find(sheet.id(), claim.getPersonId());
        Settings settings = settingsStore.find(sheet.id());
        String grade = person.gradeOn(claim.getDate());
        BigDecimal figure = ClaimFigure.live(claim, rates.findAll(sheet.id()), grade, settings, sheet.today());
        BigDecimal due = ClaimFigure.floored(claim, figure,
                ClaimFigure.lateAsOpen(claim, figure, grade, settings, sheet.today()), settings);
        BigDecimal old = claim.getSettledDue();
        claim.setSettledDue(due);
        resettlement.set(new Resettlement(old, due));
    }
}
