=== period/Period.java
/**
 * A period on a sheet: its name (unique on the sheet), its from and to dates, inclusive, whether it
 * is closed, and the due-total fixed when it was closed (null while open). A soft-closed period is
 * closed with {@code soft} set: its figures are fixed, but claims dated inside it can still change.
 */
public record Period(String sheetId, String name, LocalDate from, LocalDate to, boolean closed,
        BigDecimal closedTotal, boolean soft) {
    public Period(String sheetId, String name, LocalDate from, LocalDate to) {
        this(sheetId, name, from, to, false, null, false);
    }
    /** Whether the two periods share a day. */
    public boolean overlaps(Period other) {
        return !from.isAfter(other.to) && !other.from.isAfter(to);
    }
    /** Whether the date falls in the period. */
    public boolean contains(LocalDate date) {
        return !date.isBefore(from) && !date.isAfter(to);
    }
    /** This period, closed with its due-total fixed. */
    public Period close(BigDecimal total) {
        return new Period(sheetId, name, from, to, true, total, false);
    }
    /** This period, soft-closed with its due-total fixed. */
    public Period softClose(BigDecimal total) {
        return new Period(sheetId, name, from, to, true, total, true);
    }
    /** Whether it is closed for good: claims dated inside it cannot change. */
    public boolean hardClosed() {
        return closed && !soft;
    }
    /** This period, reopened: its due-total live again. */
    public Period reopen() {
        return new Period(sheetId, name, from, to, false, null, false);
    }
}
=== period/ClosePeriod.java
/**
 * Closes the period, fixing its due-total at this moment: the figures of the claims that counted at
 * the end of its last day, by the status their log records then (OPEN, PENDING and SETTLED, but not an
 * unbound open one dated within a hold of its person, nor one deferred now), due by a date inside it (an overdue one with its late charge), added up, skipping n/a. Each person's own figure for the period is fixed
 * too, and the period's due-total is the sum of them. A soft-closed period closes too, its figures
 * fixed afresh. A period already closed is refused, and so is a role the permission matrix does not allow to close.
 */
public class ClosePeriod {
    public void close(@Val Sheet sheet, @Val Period period, PeriodRepository periods, PersonRepository people,
            ClaimRepository claims, ClaimLogRepository log, RateRepository rates, SettingsRepository settings, RoleRepository roles,
            HttpServletRequest request, Out<Period> closedOut) throws InvalidPeriodException {
        String role = roles.roleOf(sheet.id(), Audit.user(request));
        if (!settings.find(sheet.id()).allows("close", role)) {
            throw new InvalidPeriodException("A " + role + " may not close period " + period.name());
        }
        if (period.hardClosed()) throw new InvalidPeriodException("Period " + period.name() + " is already closed");
        Period closed = fix(sheet, period, false, periods, people, claims, log, rates, settings);
        if (closed == null) throw new InvalidPeriodException("Period " + period.name() + " is already closed");
        closedOut.set(closed);
    }
    /**
     * Fixes the open (or soft-closed) period's due-total, and each person's, as at the sheet's today,
     * and marks it closed, or soft-closed when {@code soft}, in the store: the closed period, or null
     * when another request changed it first.
     */
    static Period fix(Sheet sheet, Period period, boolean soft, PeriodRepository periods, PersonRepository people,
            ClaimRepository claims, ClaimLogRepository log, RateRepository rates, SettingsRepository settings) {
        List<Rate> all = rates.findAll(sheet.id());
        Settings sheetSettings = settings.find(sheet.id());
        List<Claim> sheetClaims = claims.findAll(sheet.id());
        Map<Long, ClaimStatus> statusesThen = log.statusesOn(sheet.id(), period.to());
        BigDecimal total = BigDecimal.ZERO.setScale(2);
        Map<Long, BigDecimal> personTotals = new LinkedHashMap<>();
        for (Person person : people.findAll(sheet.id())) {
            BigDecimal personTotal = BigDecimal.ZERO.setScale(2);
            for (Claim claim : sheetClaims) {
                if (claim.getPersonId() != person.getId() || !period.contains(claim.getDueBy())) continue;
                if (!claim.countsAsOf(statusesThen.get(claim.getId()), person.heldOn(claim.getDate(), sheet.today()), sheet.today())) continue;
                BigDecimal figure = ClaimFigure.withLate(claim, all, person.gradeOn(claim.getDate()), sheetSettings, sheet.today());
                if (figure != null) personTotal = personTotal.add(figure);
            }
            personTotals.put(person.getId(), personTotal);
            total = total.add(personTotal);
        }
        Period closed = soft ? period.softClose(total) : period.close(total);
        if (!periods.markClosed(closed, period.soft())) return null;
        periods.deletePersonTotals(closed);
        periods.savePersonTotals(closed, personTotals);
        return closed;
    }
}
=== period/SoftClosePeriod.java
/**
 * Soft-closes an open period: its due-total and each person's figure are fixed as a close fixes them,
 * but claims dated inside it can still be added, edited, opened, settled and voided. The same roles
 * as may close may soft-close; a period already closed or soft-closed is refused.
 */
public class SoftClosePeriod {
    public void close(@Val Sheet sheet, @Val Period period, PeriodRepository periods, PersonRepository people,
            ClaimRepository claims, ClaimLogRepository log, RateRepository rates, SettingsRepository settings, RoleRepository roles,
            HttpServletRequest request, Out<Period> closedOut) throws InvalidPeriodException {
        String role = roles.roleOf(sheet.id(), Audit.user(request));
        if (!settings.find(sheet.id()).allows("close", role)) {
            throw new InvalidPeriodException("A " + role + " may not soft-close period " + period.name());
        }
        if (period.closed()) throw new InvalidPeriodException("Period " + period.name() + " is already closed");
        Period closed = ClosePeriod.fix(sheet, period, true, periods, people, claims, log, rates, settings);
        if (closed == null) throw new InvalidPeriodException("Period " + period.name() + " is already closed");
        closedOut.set(closed);
    }
}
=== period/ReopenPeriod.java
/**
 * Reopens a closed period, making its due-total live again. Only a role the permission matrix allows (by
 * the standing rule, a steward) may reopen; a period that
 * is not closed is refused.
 */
public class ReopenPeriod {
    public void reopen(@Val Sheet sheet, @Val Period period, PeriodRepository periods, RoleRepository roles, SettingsRepository settings,
            HttpServletRequest request, Out<Period> reopenedOut) throws InvalidPeriodException {
        String user = Audit.user(request);
        String role = roles.roleOf(sheet.id(), user);
        if (!settings.find(sheet.id()).allows("reopen", role)) {
            throw new InvalidPeriodException("A " + role + " may not reopen period " + period.name());
        }
        if (!period.closed()) throw new InvalidPeriodException("Period " + period.name() + " is not closed");
        Period reopened = period.reopen();
        if (!periods.markReopened(reopened)) {
            throw new InvalidPeriodException("Period " + period.name() + " is not closed");
        }
        periods.deletePersonTotals(reopened);
        reopenedOut.set(reopened);
    }
}
=== period/AutoClosePeriods.java
/**
 * Once the sheet's today is changed: closes every open period whose to-date plus the sheet's grace
 * days is before the new today, in order of their to-dates, exactly as a close by hand would, each
 * recording PERIOD_CLOSED with auto=yes as it closes. Nothing closes while the grace days are off.
 */
public class AutoClosePeriods {
    public void close(@Val Sheet sheet, @Val LocalDate today, PeriodRepository periods, PersonRepository people,
            ClaimRepository claims, ClaimLogRepository log, RateRepository rates, SettingsRepository settings,
            HttpServletRequest request, Audit audit) {
        Settings sheetSettings = settings.find(sheet.id());
        Sheet now = new Sheet(sheet.id(), today, sheet.archived());
        List<Period> due = periods.findAll(sheet.id()).stream()
                .filter((p) -> !p.closed() && sheetSettings.pastGrace(p.to(), today))
                .sorted(Comparator.comparing(Period::to)).toList();
        for (Period period : due) {
            Period closed = ClosePeriod.fix(now, period, false, periods, people, claims, log, rates, settings);
            if (closed == null) continue; // another request closed it first
            audit.record("PERIOD_CLOSED sheet=" + sheet.id() + " by=" + Audit.user(request)
                    + " period=" + closed.name() + " total=" + closed.closedTotal().setScale(2).toPlainString()
                    + " auto=yes");
        }
    }
}
=== period/GeneratePeriods.java
/**
 * Makes one period per calendar month from the from-date's month to the to-date's month (a blank
 * from-date is the sheet's today), each running from the first to the last day of its month and
 * named yyyy-mm. A to-date before the from-date is refused. A month whose name is already a period,
 * or whose days overlap a period on the sheet, is left out; each made is saved and audited in turn.
 */
public class GeneratePeriods {
    public void generate(@Val GeneratePeriodsInput input, @Val Sheet sheet, PeriodRepository repository,
            HttpServletRequest request, Audit audit, Out<GeneratePeriodsResponse> result)
            throws InvalidPeriodException {
        LocalDate from = input.from() == null ? sheet.today() : input.from();
        if (input.to().isBefore(from)) {
            throw new InvalidPeriodException("A to-date is on or after the from-date");
        }
        List<Period> existing = repository.findAll(sheet.id());
        int made = 0;
        for (YearMonth month = YearMonth.from(from); !month.isAfter(YearMonth.from(input.to())); month = month.plusMonths(1)) {
            Period period = new Period(sheet.id(), month.toString(), month.atDay(1), month.atEndOfMonth());
            if (existing.stream().anyMatch(o -> o.name().equals(period.name()) || o.overlaps(period))) continue;
