/**
 * Reopens a closed period, making its due-total live again. Only a role the permission matrix allows (by
 * the standing rule, a steward) may reopen; a period that
 * is not closed is refused.
 */
public class ReopenPeriod {
    public void reopen(@Val Sheet sheet, @Val Period period, PeriodRepository periods, RoleRepository roles, SettingsRepository settings,
            HttpServletRequest request, Out<Period> reopenedOut) throws InvalidPeriodException {
        String user = Audit.user(request);
        String role = roles.roleOf(sheet.id(), user);
        if (!settings.find(sheet.id()).allows("reopen", role)) {
            throw new InvalidPeriodException("A " + role + " may not reopen period " + period.name());
        }
        if (!period.closed()) throw new InvalidPeriodException("Period " + period.name() + " is not closed");
        Period reopened = period.reopen();
        if (!periods.markReopened(reopened)) {
            throw new InvalidPeriodException("Period " + period.name() + " is not closed");
        }
        periods.deletePersonTotals(reopened);
        reopenedOut.set(reopened);
    }
}
=== period/AutoClosePeriods.java
/**
 * Once the sheet's today is changed: closes every open period whose to-date plus the sheet's grace
 * days is before the new today, in order of their to-dates, exactly as a close by hand would, each
 * recording PERIOD_CLOSED with auto=yes as it closes. Nothing closes while the grace days are off.
 */
public class AutoClosePeriods {
    public void close(@Val Sheet sheet, @Val LocalDate today, PeriodRepository periods, PersonRepository people,
            ClaimRepository claims, ClaimLogRepository log, RateRepository rates, SettingsRepository settings,
            HttpServletRequest request, Audit audit) {
        Settings sheetSettings = settings.find(sheet.id());
        Sheet now = new Sheet(sheet.id(), today, sheet.archived());
        List<Period> due = periods.findAll(sheet.id()).stream()
                .filter((p) -> !p.closed() && sheetSettings.pastGrace(p.to(), today))
                .sorted(Comparator.comparing(Period::to)).toList();
        for (Period period : due) {
            Period closed = ClosePeriod.fix(now, period, false, periods, people, claims, log, rates, settings);
            if (closed == null) continue; // another request closed it first
            audit.record("PERIOD_CLOSED sheet=" + sheet.id() + " by=" + Audit.user(request)
                    + " period=" + closed.name() + " total=" + closed.closedTotal().setScale(2).toPlainString()
                    + " auto=yes");
        }
    }
}
=== period/GeneratePeriods.java
/**
 * Makes one period per calendar month from the from-date's month to the to-date's month (a blank
 * from-date is the sheet's today), each running from the first to the last day of its month and
 * named yyyy-mm. A to-date before the from-date is refused. A month whose name is already a period,
 * or whose days overlap a period on the sheet, is left out; each made is saved and audited in turn.
 */
public class GeneratePeriods {
    public void generate(@Val GeneratePeriodsInput input, @Val Sheet sheet, PeriodRepository repository,
            HttpServletRequest request, Audit audit, Out<GeneratePeriodsResponse> result)
            throws InvalidPeriodException {
        LocalDate from = input.from() == null ? sheet.today() : input.from();
        if (input.to().isBefore(from)) {
            throw new InvalidPeriodException("A to-date is on or after the from-date");
        }
        List<Period> existing = repository.findAll(sheet.id());
        int made = 0;
        for (YearMonth month = YearMonth.from(from); !month.isAfter(YearMonth.from(input.to())); month = month.plusMonths(1)) {
            Period period = new Period(sheet.id(), month.toString(), month.atDay(1), month.atEndOfMonth());
            if (existing.stream().anyMatch(o -> o.name().equals(period.name()) || o.overlaps(period))) continue;
            repository.insert(period);
            audit.record("PERIOD_ADDED sheet=" + sheet.id() + " by=" + Audit.user(request)
                    + " period=" + period.name() + " from=" + period.from() + " to=" + period.to());
            made++;
        }
        result.set(new GeneratePeriodsResponse(made));
    }
}
